INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q01', 'S1_LIT_P2', 'sohssure', '지문근거형', '(가)에서 물 한 모금을 마시고 하늘을 쳐다보는 동물은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"닭","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"사람","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"의인화 파악 실패 (행동의 주체를 사람으로 단정)"},{"choice_id":"C","text":"개구리","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"대상 파악 오류 (지문에 없는 대상 상상)"},{"choice_id":"D","text":"반딧불","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"작품 간 혼동 (나)의 대상을 (가)로 착각"},{"choice_id":"E","text":"구름","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"주어-목적어 혼동 (쳐다보는 대상을 주어로 착각)"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q02', 'S1_LIT_P2', 'sohssure', '지문근거형', '(나)에서 화자가 \'반딧불\'을 보러 가자고 한 때는 언제인가요?', NULL, 'E', '[{"choice_id":"A","text":"대낮","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"상식 오류 (\'반딧불\'은 밤에 보임) 및 어휘 무시"},{"choice_id":"B","text":"비 오는 날","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"근거 없는 정보 개입 (지문에 없는 날씨 상상)"},{"choice_id":"C","text":"보름밤","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"어휘 혼동 (그믐 vs 보름) 및 \'달조각\' 표현 오독"},{"choice_id":"D","text":"이른 아침","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"맥락 파악 오류 (어두워야 반딧불이 보임)"},{"choice_id":"E","text":"그믐밤","vector":{"어휘력":10},"error_path":"정답"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q03', 'S1_LIT_P2', 'sohssure', '어휘단독형', '다음 문장의 괄호 안에 들어갈 낱말을 바르게 쓴 것은 무엇인가요?', '달조각을 (          ) 가자.', 'D', '[{"choice_id":"A","text":"줏으러","error_path":"옛말/방언 혼동 (표준어 아님)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"B","text":"주으러","error_path":"불규칙 활용 오류 (흔한 실수)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"C","text":"줍으러","error_path":"기본형 \'줍다\'를 그대로 활용하려 함 (심각한 활용 오류)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"D","text":"주우러","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"E","text":"주러","error_path":"다른 단어 \'주다\'와 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q04', 'S1_LIT_P2', 'sohssure', '논리추론형', '(가)에서 닭이 물을 먹고 하늘을 쳐다보는 이유는 무엇일까요? (가장 적절한 감상)', NULL, 'A', '[{"choice_id":"A","text":"물을 주신 하늘에 감사하는 마음으로","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"목이 아파서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"문학적 상황을 생물학적/현실적 문제로 오해"},{"choice_id":"C","text":"구름의 개수를 세어 보려고","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"지엽적 정보(구름)에 집착한 단순 추론"},{"choice_id":"D","text":"구름이 먹고 싶어서","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"상식 및 문맥 파악의 심각한 오류"},{"choice_id":"E","text":"하늘에 날아가는 새가 부러워서","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"근거 없는 인과 관계 추론"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q05', 'S1_LIT_P2', 'sohssure', '지문근거형', '(나)에서 \'부서진 달조각\'은 무엇을 가리키는 말인가요?', NULL, 'B', '[{"choice_id":"A","text":"깨진 유리","vector":{"국어 개념 적용 능력":-5,"어휘력":-5},"error_path":"비유적 표현의 문자적 해석 오류 (Metaphor Literalism)"},{"choice_id":"B","text":"반딧불","vector":{"국어 개념 적용 능력":10,"어휘력":10},"error_path":"정답"},{"choice_id":"C","text":"물방울","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"시각적 이미지의 자의적 연결 (빛나는 것=물방울)"},{"choice_id":"D","text":"별","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"지문에 없는 대상 연상 (유사 소재 혼동)"},{"choice_id":"E","text":"돌멩이","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"맥락과 무관한 사물 선택 (부서진 것=돌)"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q06', 'S1_LIT_P2', 'sohssure', '논리추론형', '(나)의 화자(말하는 이)가 친구에게 하고 싶은 말로 가장 알맞은 것은 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"반딧불 잡아다가 불을 켜자.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"형설지공(螢雪之功) 고사의 과도한 적용 및 기능적 해석"},{"choice_id":"B","text":"우리 같이 숲으로 가서 반딧불을 찾자.","vector":{"국어 개념 적용 능력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"숲은 위험하니까 절대 가면 안 돼.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"정서/태도 파악 오류 (제안과 반대되는 금지)"},{"choice_id":"D","text":"숲을 깨끗하게 청소하자.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"도덕적 당위의 부적절한 개입 (Camouflage Disguise)"},{"choice_id":"E","text":"달조각을 주워서 팔러 가자.","vector":{"국어 관련 배경지식":-5,"논리 사고력":-5},"error_path":"동심적 상황에 대한 세속적/경제적 해석 오류"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q07', 'S1_LIT_P2', 'sohssure', '어휘단독형', '(나)의 \'달조각을 주우러\'에서 \'주우러\'와 바꿔 쓰기에 가장 알맞은 말은?', NULL, 'B', '[{"choice_id":"A","text":"버리러","vector":{"어휘력":-5},"error_path":"반의어 선택 오류"},{"choice_id":"B","text":"찾으러","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"C","text":"모으러","vector":{"어휘력":-5},"error_path":"유사 의미어의 미세한 뉘앙스 차이 (단순 수집 vs 탐색 후 습득)"},{"choice_id":"D","text":"만들러","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"행위의 성격 파악 오류 (발견 vs 제작)"},{"choice_id":"E","text":"먹으러","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"동심적 표현(달조각)을 식욕/음식으로 오해"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q08', 'S1_LIT_P2', 'sohssure', '논리추론형', '(가)를 읽고 떠오르는 생각이나 느낌으로 알맞은 것은?', NULL, 'C', '[{"choice_id":"A","text":"하늘이 무너질까 봐 걱정스러워.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"기우(杞憂) 고사성어의 부적절한 개입 및 과도한 상상"},{"choice_id":"B","text":"할 일이 없어서 심심해 보여.","vector":{"논리 사고력":-5,"국어 개념 적용 능력":-5},"error_path":"행위의 의미(물 마심=생존/감사) 파악 실패"},{"choice_id":"C","text":"작은 일에도 감사하는 마음이 느껴져.","vector":{"국어 개념 적용 능력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"빨리 물을 마셔야 해서 급한 느낌이야.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"정서 파악 오류 (여유로움 vs 조급함)"},{"choice_id":"E","text":"혼자 있어서 외롭고 쓸쓸해 보여.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"객관적 상황을 부정적 정서(고독)로 왜곡"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q09', 'S1_LIT_P2', 'sohssure', '서술형', '(가) 시에서 닭은 물 한 모금을 마시고 무엇을 쳐다보는지 두 가지를 찾아 쓰시오.', NULL, NULL, '[]', '하늘, 구름', '[{"criteria_id":1,"condition":"하늘과 구름(또는 둘 중 하나)을 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q10', 'S1_LIT_P2', 'sohssure', '서술형', '(나) 시에서 친구들은 숲으로 무엇을 주우러 가자고 했는지 쓰시오.', NULL, NULL, '[]', '달조각 (또는 반딧불)', '[{"criteria_id":1,"condition":"달조각 또는 반딧불을 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q01', 'S1_LIT_P3', 'sohssure', '지문근거형', '(가)에서 말하는 이가 살고 싶어 하는 곳은 어디인가요?', NULL, 'D', '[{"choice_id":"A","text":"뒷문 밖","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 속 장소(갈잎의 노래가 있는 곳)를 목적지로 착각"},{"choice_id":"B","text":"깊은 산속","vector":{"비문학 배경지식":-5,"문장 독해력":-5},"error_path":"일반적인 은거지 이미지에 기댄 추측 오류"},{"choice_id":"C","text":"도시","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"시의 정서(자연)와 정반대되는 공간 선택"},{"choice_id":"D","text":"강변","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"E","text":"바닷가","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'금모래\'라는 단어에서 연상된 오답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q02', 'S1_LIT_P3', 'sohssure', '어휘단독형', '(나)의 \'하얀 쪽배\'에서 \'쪽배\'의 뜻으로 가장 알맞은 것은?', NULL, 'E', '[{"choice_id":"A","text":"맛있는 과일","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'배\'의 동음이의어(과일) 혼동"},{"choice_id":"B","text":"물건을 파는 가게","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"\'배\'라는 글자의 동음이의어 혼동 또는 문맥 상실"},{"choice_id":"C","text":"하늘을 나는 비행기","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"은하수/하늘이라는 배경에만 주목하여 운송수단 오해"},{"choice_id":"D","text":"아주 큰 여객선","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"단어의 뜻(작다)과 정반대되는 크기 선택"},{"choice_id":"E","text":"작고 좁은 배","vector":{"어휘력":10},"error_path":"정답"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q03', 'S1_LIT_P3', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 낱말로 알맞은 것은 무엇인가요?', '쪽배에 꿈을 (          ) 은하수로 갔다.', 'D', '[{"choice_id":"A","text":"씯고","error_path":"없는 말","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"B","text":"싿고","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"C","text":"실고","error_path":"\'ㄹ\' 받침 오류 (불규칙 활용 미숙지)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"D","text":"싣고","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"E","text":"싯고","error_path":"받침 오류 (심각)","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q04', 'S1_LIT_P3', 'sohssure', '논리추론형', '(가)에서 첫 번째 행과 마지막 행이 같은 것은 어떤 효과를 주나요?', NULL, 'A', '[{"choice_id":"A","text":"운율을 형성하고 의미를 강조한다","vector":{"구조 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"글을 읽는 속도를 빠르게 한다","vector":{"구조 독해력":-5,"국어 관련 배경지식":-5},"error_path":"반복의 기능(안정감)과 반대되는 효과(속도감) 선택"},{"choice_id":"C","text":"새로운 사건이 시작됨을 암시한다","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"반복의 의미(지속/강조)와 상충되는 해석(새로운 시작)"},{"choice_id":"D","text":"이야기가 끝났음을 알려 준다","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"단순한 종료 신호로 오해 (수미상관의 구조적 미학 간과)"},{"choice_id":"E","text":"등장인물의 성격이 변했음을 보여 준다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"동일한 소망의 반복을 성격 변화로 잘못 해석"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q05', 'S1_LIT_P3', 'sohssure', '지문근거형', '(나)에서 길을 잃지 않게 도와주는 \'등대\' 역할을 하는 것은 무엇인가요?', NULL, 'C', '[{"choice_id":"A","text":"돛대","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"배의 부속품(없는 것)을 있는 것으로 착각"},{"choice_id":"B","text":"계수나무","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"본문에 나오는 다른 소재와 혼동 (배 안에 있는 사물)"},{"choice_id":"C","text":"샛별","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"은하수","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"배경 공간을 길잡이 역할로 오해"},{"choice_id":"E","text":"토끼","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"본문의 등장 동물을 길잡이로 오해"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q06', 'S1_LIT_P3', 'sohssure', '논리추론형', '(가)와 (나)를 읽고 난 뒤의 느낌으로 가장 알맞은 것은?', NULL, 'D', '[{"choice_id":"A","text":"화가 나고 답답하다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"부정적인 감정으로 오해"},{"choice_id":"B","text":"시끄럽고 정신이 없다","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"고요하고 정적인 분위기를 오해"},{"choice_id":"C","text":"슬프고 눈물이 날 것 같다","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"일반적인 이별 노래의 정서를 잘못 적용"},{"choice_id":"D","text":"아름답고 평화로운 느낌이 든다","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"무섭고 조마조마한 느낌이 든다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"정서와 정반대되는 감정 (공포)"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q07', 'S1_LIT_P3', 'sohssure', '어휘단독형', '(가)의 \'갈잎\'은 무엇의 줄임말인가요?', NULL, 'C', '[{"choice_id":"A","text":"가을 잎","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"비슷한 발음(가을)에서 유추한 오답"},{"choice_id":"B","text":"가는 잎","vector":{"어휘력":-5,"구조 독해력":-5},"error_path":"모양(가늘다)에서 유추한 오답"},{"choice_id":"C","text":"갈대 잎","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"갈라진 잎","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"형태(갈라지다)에서 유추한 오답"},{"choice_id":"E","text":"갈색 잎","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"색깔(갈색)에서 유추한 오답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q08', 'S1_LIT_P3', 'sohssure', '논리추론형', '(나)에서 \'구름 나라\'는 어떤 곳일까요? 가장 알맞은 상상을 골라 보세요.', NULL, 'E', '[{"choice_id":"A","text":"자동차들이 쌩쌩 달리는 도로","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"현실 세계의 복잡한 모습을 잘못 투영"},{"choice_id":"B","text":"아무것도 없는 텅 빈 사막","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"구름/은하수/계수나무 등 풍부한 소재를 무시"},{"choice_id":"C","text":"시끄럽고 먼지가 많은 공사장","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"깨끗하고 푸른 하늘 이미지와 정반대"},{"choice_id":"D","text":"무섭고 캄캄한 동굴 같은 곳","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"반짝이는 샛별/은하수 이미지와 정반대"},{"choice_id":"E","text":"꿈속처럼 신비롭고 재미있는 곳","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q09', 'S1_LIT_P3', 'sohssure', '서술형', '(가) 시에서 \'뜰\'과 \'뒷문 밖\'에 각각 무엇이 있다고 했는지 찾아 쓰시오.', NULL, NULL, '[]', '뜰에는 금모래 빛, 뒷문 밖에는 갈잎의 노래', '[{"criteria_id":1,"condition":"금모래 빛과 갈잎의 노래를 정확하게 찾아 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q10', 'S1_LIT_P3', 'sohssure', '서술형', '(나) 시에서는 무엇이 \'등대\' 역할을 한다고 했는지 쓰시오.', NULL, NULL, '[]', '샛별', '[{"criteria_id":1,"condition":"\'샛별\'이라고 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q01', 'S1_LIT_P4', 'sohssure', '지문근거형', '(가)에서 동생이 지난밤에 한 행동은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"이불에 오줌을 쌌다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"정말로 지도를 그렸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"비유적 표현(지도)을 사실적 행위(그림 그리기)로 오해"},{"choice_id":"C","text":"빨래를 걷어 왔다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"배경(빨랫줄)을 주체의 행동으로 오해"},{"choice_id":"D","text":"진짜로 돈을 주웠다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈속의 내용을 현실의 행동으로 착각"},{"choice_id":"E","text":"형과 싸웠다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"지문에 없는 내용을 상상"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q02', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)에서 동생이 아침에 \'소금\'을 얻으러 간 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"오줌을 싼 벌로 심부름을 가서","vector":{"국어 관련 배경지식":10,"논리 사고력":10},"error_path":"정답 (한국의 전통 풍습 배경지식 활용)"},{"choice_id":"B","text":"아침 반찬을 만들어야 해서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"소금의 일상적 용도(요리)만 생각"},{"choice_id":"C","text":"꿈속에서 돈을 잃어버려서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈 내용과 현실 행동을 잘못 연결"},{"choice_id":"D","text":"빨래를 깨끗하게 하려고","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"빨랫줄 이미지와 소금의 세탁 효과(일반상식) 혼동"},{"choice_id":"E","text":"지도를 그리기 위해서","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"소금과 지도 그리기의 인과 관계 오류"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q03', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)에서 \'지도\'는 실제로 무엇을 가리키나요?', NULL, 'A', '[{"choice_id":"A","text":"이불에 오줌을 싼 자국","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"우리나라의 모습","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"지도의 사전적 의미만 생각"},{"choice_id":"C","text":"보물섬으로 가는 길","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈속 내용(돈 주워 넣고)과 상상을 혼동"},{"choice_id":"D","text":"동생이 그린 그림","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"\'그린\'이라는 표현을 곧이곧대로 해석"},{"choice_id":"E","text":"아침에 해가 뜨는 모양","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문과 관계없는 내용 선택"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q04', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)를 읽을 때 느껴지는 리듬감에 대한 설명으로 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"\'오줌 쏴 눈 지도\'라는 말이 반복되어 리듬이 생긴다","vector":{"구조 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답 (반복을 통한 운율 형성)"},{"choice_id":"B","text":"글자 수가 모두 똑같아서 리듬이 생긴다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"글자 수(음수율)의 변화(3/4조 등)를 무시하고 획일적으로 판단"},{"choice_id":"C","text":"이야기를 하듯이 길게 이어져서 리듬이 없다","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"운율이 있는 시를 산문으로 오해"},{"choice_id":"D","text":"아무런 반복이 없어서 리듬이 느껴지지 않는다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"명백히 존재하는 반복을 파악하지 못함"},{"choice_id":"E","text":"첫 글자가 모두 같아서 리듬이 생긴다","vector":{"구조 독해력":-5,"어휘력":-5},"error_path":"두운(첫 글자 반복)이 나타나지 않는데 있다고 착각"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q05', 'S1_LIT_P4', 'sohssure', '논리추론형', '(나)에서 \'파 보나 마나\'라고 말한 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"꽃의 색깔과 감자의 색깔이 똑같아서","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"감자를 파는 것이 귀찮아서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"화자의 태도(게으름)로 오해"},{"choice_id":"C","text":"감자가 아직 다 자라지 않아서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"농사 지식(수확 시기)과 혼동"},{"choice_id":"D","text":"누가 이미 감자를 다 캐가서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 상황 상상"},{"choice_id":"E","text":"감자 꽃이 시들어 버려서","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"꽃의 상태를 이유로 착각"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q06', 'S1_LIT_P4', 'sohssure', '어휘단독형', '(나)에서 \'파 보나 마나\'라는 말의 뜻으로 가장 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"결과가 뻔해서 확인할 필요도 없이","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"땅을 파는 것이 너무 힘들어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"행위의 어려움으로 오해"},{"choice_id":"C","text":"아무리 파 봐도 알 수가 없어서","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"의미를 반대(불확실성)로 해석"},{"choice_id":"D","text":"조금만 파도 금방 나오기 때문에","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"시간의 빠름으로 오해"},{"choice_id":"E","text":"남들이 보지 않을 때 몰래","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"비밀스러운 행동으로 오해"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q07', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)를 읽을 때 드는 느낌으로 가장 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"재미있고 웃음이 난다","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답 (해학적 정서)"},{"choice_id":"B","text":"슬프고 눈물이 난다","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"정반대의 정서(비극) 선택"},{"choice_id":"C","text":"무섭고 깜짝 놀란다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"공포/놀람으로 오해"},{"choice_id":"D","text":"지루하고 하품이 난다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"감상의 부재 또는 흥미 없음 선택"},{"choice_id":"E","text":"화가 나고 답답하다","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"부정적 정서(분노) 선택"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q08', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)에 공통으로 나오는 소재는 아니지만, 둘 다 우리 주변에서 흔히 볼 수 있는 것은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"가족과 자연","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 ((가) 동생/오줌, (나) 감자/꽃 - 일상적 소재)"},{"choice_id":"B","text":"전쟁과 군인","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전혀 다른 무거운 주제 선택"},{"choice_id":"C","text":"왕자와 공주","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"동화 속 환상적인 소재 오해"},{"choice_id":"D","text":"우주선과 외계인","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"SF적 소재 오해"},{"choice_id":"E","text":"로봇과 컴퓨터","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"현대 기술 문명 소재 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q09', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)의 \'동생\'에게 해주고 싶은 말로 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"괜찮아, 다음부터는 자기 전에 화장실에 다녀오렴","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (따뜻한 위로와 조언)"},{"choice_id":"B","text":"지도를 아주 잘 그렸구나, 화가 해도 되겠다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황(실수)을 칭찬하는 엉뚱한 반응"},{"choice_id":"C","text":"꿈속에서 돈을 잃어버려서 정말 안타깝다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"핵심 사건(오줌)이 아닌 꿈 내용에만 반응"},{"choice_id":"D","text":"소금을 더 많이 받아와야지","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"벌을 더 받으라는 부정적 반응"},{"choice_id":"E","text":"빨래는 네가 다 해야 해","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지나치게 가혹한 반응"}]', NULL, NULL, NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q10', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)에 대한 설명으로 알맞지 않은 것은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"(나)는 감자 꽃의 색깔이 감자의 색깔과 다르다고 말한다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (틀린 내용 찾기: 같다고 말함)"},{"choice_id":"B","text":"(가)는 4행시처럼 \'지도\'라는 말로 끝난다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 전제 누락"},{"choice_id":"C","text":"(가)의 \'지도\'는 오줌을 싼 자국을 빗댄 말이다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"부정형 문항 오독: 인과 관계 왜곡"},{"choice_id":"D","text":"(나)의 자주 감자는 자주 꽃이 핀다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 조건 혼동"},{"choice_id":"E","text":"(가)와 (나)는 모두 짧지만 의미가 담겨 있다","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 범위 과확대"}]', NULL, NULL, NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q01', 'S1_NON_P2', 'sohssure', '지문근거형', '이 글은 어떤 동물에 대한 설명인가요?', NULL, 'C', '[{"choice_id":"A","text":"늑대","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"정보 위계 파악 실패 (예시로 든 동물을 메인으로 인지)"},{"choice_id":"B","text":"사자","vector":{"어휘력":-5,"비문학 배경지식":-5},"error_path":"지문에 없는 강한 동물 상상"},{"choice_id":"C","text":"토끼","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"D","text":"호랑이","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"중심 화제 파악 오류 (지문에 등장하는 천적 선택)"},{"choice_id":"E","text":"거북이","vector":{"비문학 배경지식":-5,"국어 관련 배경지식":-5},"error_path":"지문에 없는 대상 선택 (전래동화 연상)"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q02', 'S1_NON_P2', 'sohssure', '지문근거형', '토끼가 적이 나타나면 빨리 도망가야 하는 이유는 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"더위를 식히기 위해서","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"정보 간섭 (귀의 다른 기능인 \'체온 조절\'과 혼동)"},{"choice_id":"B","text":"숲속에서 약한 동물이라서","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"친구들을 만나러 가려고","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"문맥에 없는 사회적 이유 상상"},{"choice_id":"D","text":"귀가 너무 무거워서","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"신체적 특징(큰 귀)과 행동의 인과 관계 오류"},{"choice_id":"E","text":"다리 운동을 하고 싶어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"행동의 목적을 임의로 추측 (운동)"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q03', 'S1_NON_P2', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?', '토끼 귀는 몸의 열을 (          ) 줍니다.', 'B', '[{"choice_id":"A","text":"씻겨","error_path":"\'씻기다\'와 혼동 (문맥 파악 실패)","vector":{"어법·문법 능력":-2,"문장 독해력":-3}},{"choice_id":"B","text":"식혀","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"C","text":"시켜","error_path":"\'시키다\'와 혼동 (발음 유사)","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"D","text":"시겨","error_path":"없는 말 (심각한 철자 오류)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"E","text":"식여","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q04', 'S1_NON_P2', 'sohssure', '지문근거형', '더운 여름에 토끼의 큰 귀는 어떤 역할을 하나요?', NULL, 'D', '[{"choice_id":"A","text":"다른 동물들에게 예쁘게 보이게 해요.","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"심미적 기능에 대한 주관적 판단 개입"},{"choice_id":"B","text":"부채처럼 흔들어서 바람을 만들어요.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"유사 기능(시원함)에 대한 물리적 오개념 (부채질)"},{"choice_id":"C","text":"햇볕을 가려서 그늘을 만들어요.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"형태적 특징(크다)에 기반한 자의적 추측 (그늘막)"},{"choice_id":"D","text":"몸의 열을 밖으로 내보내 시원하게 해 줘요.","vector":{"문장 독해력":10,"어휘력":10},"error_path":"정답"},{"choice_id":"E","text":"빗물을 받아서 마실 수 있게 해요.","vector":{"비문학 배경지식":-5,"문장 독해력":-5},"error_path":"지문과 무관한 기능 상상 (물 컵)"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q05', 'S1_NON_P2', 'sohssure', '어휘단독형', '이 글에서 \'식혀 주는\'과 바꿔 쓰기에 가장 알맞은 말은 무엇인가요?', NULL, 'C', '[{"choice_id":"A","text":"만들어 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"문맥상 반대 의미 선택 (제거 vs 생성)"},{"choice_id":"B","text":"참아 주는","vector":{"어휘력":-5,"국어 개념 적용 능력":-5},"error_path":"단어의 주체 혼동 (참는 것은 생물, 여기선 기능)"},{"choice_id":"C","text":"없애 주는","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"더해 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"문맥상 반대 의미 선택 (감소 vs 증가)"},{"choice_id":"E","text":"피해 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"유사 문맥(피하다)과의 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q06', 'S1_NON_P2', 'sohssure', '논리추론형', '글쓴이가 토끼의 귀를 \'보물\'이라고 표현한 이유는 무엇인가요?', NULL, 'D', '[{"choice_id":"A","text":"친구들이 서로 가지고 싶어 해서","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"희소성에 기반한 소유욕으로 오해"},{"choice_id":"B","text":"시장에 내다 팔면 비싼 값을 받을 수 있어서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"\'보물\'의 경제적 가치에만 주목한 해석 오류"},{"choice_id":"C","text":"땅속 깊은 곳에 숨겨져 있어서","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"\'보물 찾기\' 놀이와의 혼동"},{"choice_id":"D","text":"토끼의 생명을 지켜 주는 중요한 것이라서","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"보석처럼 반짝반짝 빛이 나서","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"비유적 표현의 시각적/문자적 해석 오류"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q07', 'S1_NON_P2', 'sohssure', '논리추론형', '다음 문장에 들어갈 말로 가장 알맞은 것은 무엇인가요?\n"토끼는 숲속에서 약한 동물이에요. (    ) 적이 나타나면 빨리 도망가야 해요."', NULL, 'C', '[{"choice_id":"A","text":"왜냐하면","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"인과 관계의 방향 혼동 (결과가 뒤에 오는데 원인을 이끄는 말 선택)"},{"choice_id":"B","text":"하지만","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"문맥 파악 오류 (인과 관계를 대조 관계로 오해)"},{"choice_id":"C","text":"그래서","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"그리고","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"문맥 파악 오류 (인과 관계를 단순 나열로 오해)"},{"choice_id":"E","text":"만약","vector":{"어휘력":-5,"구조 독해력":-5},"error_path":"가정 상황을 나타내는 말로 오해 (사실 진술임)"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q08', 'S1_NON_P2', 'sohssure', '논리추론형', '글의 내용으로 미루어 볼 때, 토끼의 특징으로 알맞은 것은 무엇인가요?', NULL, 'E', '[{"choice_id":"A","text":"몸집이 커서 호랑이와 싸워 이길 수 있다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전제(약한 동물)를 부정하는 심각한 독해 오류"},{"choice_id":"B","text":"다리가 짧아서 적에게 잡히기 쉽다.","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"행동 결과(빨리 도망간다)와 모순되는 추론"},{"choice_id":"C","text":"귀가 작아서 소리를 잘 듣지 못한다.","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"지문(귀가 길다, 잘 듣는다)과 정반대 사실 선택"},{"choice_id":"D","text":"땀을 아주 많이 흘려서 더위를 식힌다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문 정보(땀 안 흘림)의 정반대 선택"},{"choice_id":"E","text":"땀을 흘리는 대신 귀로 열을 내보낸다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q09', 'S1_NON_P2', 'sohssure', '서술형', '토끼의 귀는 소리를 듣는 일 말고 어떤 일을 하는지 지문에서 한 가지만 찾아 쓰시오.', NULL, NULL, '[]', '더위를 식혀 줍니다. (또는 몸의 열을 밖으로 내보냅니다.)', '[{"criteria_id":1,"condition":"더위를 식히거나 열을 내보낸다는 내용 포함","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q10', 'S1_NON_P2', 'sohssure', '서술형', '글쓴이는 마지막 문단에서 토끼의 귀를 무엇이라고 불렀는지 쓰시오.', NULL, NULL, '[]', '보물 (또는 아주 중요한 보물)', '[{"criteria_id":1,"condition":"\'보물\'이라는 단어를 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q01', 'S1_NON_P3', 'sohssure', '지문근거형', '이 글은 무엇에 대해 설명하고 있나요?', NULL, 'E', '[{"choice_id":"A","text":"바닷속 물고기들의 생활","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'바다\'라는 단어에 이끌려 전혀 다른 주제 선택"},{"choice_id":"B","text":"시원한 물을 마시는 법","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"마지막 문장의 세부 정보를 전체 주제로 착각"},{"choice_id":"C","text":"눈과 얼음의 차이점","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"지문 일부분(눈에 대한 언급)을 전체 주제로 확대 해석"},{"choice_id":"D","text":"식물이 잘 자라는 방법","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"마지막 문장의 부수적 효과를 전체 주제로 오해"},{"choice_id":"E","text":"구름과 비가 만들어지는 과정","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q02', 'S1_NON_P3', 'sohssure', '지문근거형', '이 글에서 \'수증기\'에 대한 설명으로 알맞지 않은 것은?', NULL, 'A', '[{"choice_id":"A","text":"눈에 잘 보이고 매우 무겁다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (틀린 내용 찾기: \'눈에 보이지 않을 만큼 작고 가볍다\'고 설명됨)"},{"choice_id":"B","text":"물이 햇볕을 받아 변한 것이다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"C","text":"하늘 높이 올라간다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"D","text":"아주 작고 가볍다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"E","text":"찬 공기를 만나면 물방울로 변한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 과도한 일반화"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q03', 'S1_NON_P3', 'sohssure', '어휘단독형', '다음 문장의 괄호 안에 들어갈 말로 알맞은 것은 무엇인가요?', '수증기가 찬 공기와 (          ) 물방울이 되었다.', 'B', '[{"choice_id":"A","text":"부딧쳐","error_path":"받침 오류 (심각)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"B","text":"부딪쳐","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"C","text":"부딪혀","error_path":"피동/능동 혼동 (문맥상 어색)","vector":{"어법·문법 능력":-2,"문장 독해력":-2}},{"choice_id":"D","text":"부디쳐","error_path":"소리 나는 대로 잘못 쓴 표기","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"E","text":"부딫쳐","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q04', 'S1_NON_P3', 'sohssure', '지문근거형', '비가 아니라 \'눈\'이 되어 내리기 위한 조건은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"날씨가 아주 추워야 한다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"햇볕이 아주 강하게 비쳐야 한다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"눈이 녹는 조건을 생성 조건으로 착각"},{"choice_id":"C","text":"바닷물이 더 많이 증발해야 한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"강수량 증가 원인을 강수 형태 변화 원인으로 오해"},{"choice_id":"D","text":"바람이 아주 세게 불어야 한다","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"강설 조건(기온)을 풍속으로 오해"},{"choice_id":"E","text":"구름이 아주 높이 떠 있어야 한다","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"구름의 위치와 강수의 형태 혼동"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q05', 'S1_NON_P3', 'sohssure', '어휘단독형', '이 글에서 물이 바다, 하늘, 땅을 돌고 도는 것을 무엇에 비유했나요?', NULL, 'C', '[{"choice_id":"A","text":"이사","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"장소를 옮긴다는 점(이동)만 생각한 오답"},{"choice_id":"B","text":"소풍","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"비슷한 개념(놀러감)과 혼동"},{"choice_id":"C","text":"여행","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"놀이","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"즐거운 활동이라는 점에서 착각"},{"choice_id":"E","text":"공부","vector":{"논리 사고력":-5,"어휘력":-5},"error_path":"비유적 표현과 전혀 관계없는 단어 선택"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q06', 'S1_NON_P3', 'sohssure', '어휘단독형', '이 글에서 \'둥둥\'은 어떤 모양을 나타내는 말인가요?', NULL, 'A', '[{"choice_id":"A","text":"물이나 공기 중에 가볍게 떠 있는 모양","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"아기들이 걷는 모양","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'아장아장\'과 같은 의태어와 혼동"},{"choice_id":"C","text":"북을 칠 때 나는 소리","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"동음이의어(북소리 둥둥) 혼동 (문맥 무시)"},{"choice_id":"D","text":"바람이 아주 세게 부는 모양","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'씽씽\'과 같은 의태어와 혼동"},{"choice_id":"E","text":"무거운 물건이 바닥에 떨어지는 소리","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'쿵쿵\'과 같은 소리 흉내말과 혼동"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q07', 'S1_NON_P3', 'sohssure', '지문근거형', '물방울의 여행 덕분에 일어나는 좋은 일은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"식물들이 잘 자라고 시원한 물을 마실 수 있다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"하늘이 더 높고 파랗게 변한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문과 관계없는 일반적인 날씨 묘사 선택"},{"choice_id":"C","text":"햇볕이 더 뜨겁게 비친다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"물의 순환과 무관한 자연 현상 선택"},{"choice_id":"D","text":"바닷물이 점점 줄어든다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"순환(유지)의 개념과 반대되는 현상(고갈) 선택"},{"choice_id":"E","text":"구름이 영원히 사라지지 않는다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"과정의 일부(구름)를 영구적인 상태로 오해"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q08', 'S1_NON_P3', 'sohssure', '논리추론형', '물방울이 이동하는 순서로 알맞은 것은?', NULL, 'C', '[{"choice_id":"A","text":"바다 -> 땅 -> 구름 -> 하늘","vector":{"구조 독해력":-5,"비문학 배경지식":-5},"error_path":"비가 내리는 과정(구름->땅)을 반대로 이해"},{"choice_id":"B","text":"하늘 -> 바다 -> 땅 -> 구름","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"순서를 뒤죽박죽 섞음"},{"choice_id":"C","text":"바다 -> 하늘 -> 구름 -> 땅 -> 바다","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"구름 -> 하늘 -> 바다 -> 땅","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"비가 땅으로 내리는 과정을 생략하거나 순서 오해"},{"choice_id":"E","text":"땅 -> 구름 -> 하늘 -> 바다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"땅에서 하늘로 바로 올라가는(증발 위치) 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q09', 'S1_NON_P3', 'sohssure', '서술형', '하늘 높이 올라간 수증기가 찬 공기를 만나 변한 작은 물방울들이 많이 모여서 무엇이 되는지 쓰시오.', NULL, NULL, '[]', '구름', '[{"criteria_id":1,"condition":"\'구름\'이라고 씀","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q10', 'S1_NON_P3', 'sohssure', '서술형', '물의 여행 덕분에 우리나 식물이 어떤 도움을 받는지 지문에서 한 가지만 찾아 쓰시오.', NULL, NULL, '[]', '식물이 무럭무럭 자랄 수 있습니다. (또는 우리가 시원한 물을 마실 수 있습니다.)', '[{"criteria_id":1,"condition":"식물이 자라거나 물을 마실 수 있다는 내용 포함","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q01', 'S1_NON_P4', 'sohssure', '지문근거형', '자석의 N극이 가리키는 방향은 어디인가요?', NULL, 'A', '[{"choice_id":"A","text":"북쪽","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"남쪽","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"S극이 가리키는 방향과 혼동"},{"choice_id":"C","text":"동쪽","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문에 나오지 않는 방향 (해 뜨는 곳) 선택"},{"choice_id":"D","text":"서쪽","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문에 나오지 않는 방향 (해 지는 곳) 선택"},{"choice_id":"E","text":"위쪽","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"나침반의 평면 방향이 아닌 수직 방향 오해"}]', NULL, NULL, NULL, 1);
