INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q06', 'F1_NON_P5', 'frege', '지문근거형', '이 글에서 설명하는 훈민정음의 특징이 아닌 것은?', NULL, 'D', '[{"choice_id":"A","text":"창제 동기가 숭고하다","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"B","text":"독창적인 글자이다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"C","text":"세계적으로 우수성을 인정받고 있다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"D","text":"배우기가 매우 어렵다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"E","text":"제자 원리가 과학적이다","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"부정형 문항 오독: 과도한 일반화"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q07', 'F1_NON_P5', 'frege', '논리추론형', '유네스코에서 주는 \'세종대왕 문해상\'은 어떤 사람들에게 주는 상일까요?', NULL, 'C', '[{"choice_id":"A","text":"한국 역사를 세계에 널리 알린 사람","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"역사 홍보와 혼동"},{"choice_id":"B","text":"새로운 글자를 많이 발명한 사람","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"문맹 퇴치를 발명으로 오해"},{"choice_id":"C","text":"글을 모르는 사람들을 위해 글을 가르치고 문맹 퇴치에 힘쓴 사람","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"과학 기술 발전에 기여한 사람","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"과학적 원리와 현대 과학 기술 혼동"},{"choice_id":"E","text":"세종 대왕의 업적을 연구한 학자","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"연구 업적과 공로상 혼동"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q08', 'F1_NON_P5', 'frege', '논리추론형', '이 글의 내용 전개 방식으로 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"창제 동기를 밝히고 제자 원리를 나누어 설명하고 있다","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"세종 대왕의 어린 시절 일화를 소개하고 있다","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"전기적 구성으로 오해"},{"choice_id":"C","text":"훈민정음과 한자의 차이점을 대조하고 있다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"주된 전개 방식이 아님(일부 언급)"},{"choice_id":"D","text":"훈민정음이 만들어진 과정을 시간 순서대로 기록하고 있다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"서사적 구성으로 오해"},{"choice_id":"E","text":"글자의 모양이 변해온 역사를 설명하고 있다","vector":{"구조 독해력":-5,"비문학 배경지식":-5},"error_path":"역사적 변천 과정으로 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q09', 'F1_NON_P5', 'frege', '서술형', '훈민정음의 자음은 사람의 무엇을 본떠 만들었는지 쓰시오.', NULL, NULL, '[]', '발음 기관 (입, 혀, 목구멍 등)', '[{"criteria_id":1,"condition":"발음 기관(또는 구체적 신체 부위)을 언급함","score":10,"vector":{"문장 독해력":10,"국어 관련 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q10', 'F1_NON_P5', 'frege', '서술형', '세종 대왕이 훈민정음을 만든 가장 큰 이유는 무엇입니까?', NULL, NULL, '[]', '백성들이 글자를 몰라 겪는 어려움을 해결하고, 누구나 쉽게 글을 쓰고 읽게 하기 위해서입니다.', '[{"criteria_id":1,"condition":"백성을 사랑하는 마음(애민 정신)이나 쉬운 글자를 보급하려는 의도를 씀","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q01', 'R1_LIT_P3', 'russell', '지문근거형', '(가)에 대한 설명으로 가장 적절한 것은?', NULL, 'A', '[{"choice_id":"A","text":"(가)는 후렴구를 반복하여 주제를 강조하고 운율을 형성한다.","vector":{"문장 독해력":10,"구조 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"(가)와 (나)는 모두 시간에 따른 공간의 이동을 중심으로 서사가 전개된다.","vector":{"구조 독해력":-3,"논리 사고력":-2},"error_path":"과도한 일반화"},{"choice_id":"C","text":"(가)는 시각적 이미지만을, (나)는 청각적 이미지만을 사용하여 대상을 묘사한다.","vector":{"문장 독해력":-4,"국어 개념 적용 능력":-3},"error_path":"지문 근거 누락"},{"choice_id":"D","text":"(나)는 전지적 작가 시점을 통해 주인공의 내면 심리를 서술자가 직접 제시하지 않고 대화로만 보여준다.","vector":{"구조 독해력":-5,"국어 개념 적용 능력":-3},"error_path":"세부 정보 오독"},{"choice_id":"E","text":"(가)는 현실 비판적 태도를, (나)는 목가적이고 평화로운 분위기를 드러낸다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"핵심 정보 혼동"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q02', 'R1_LIT_P3', 'russell', '논리추론형', '(나)의 \'이인국 박사\'에 대한 평가로 가장 적절한 것은?', NULL, 'B', '[{"choice_id":"A","text":"시대의 변화에 순응하며 도덕적 가치를 지키려고 노력한 인물이다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전제 누락"},{"choice_id":"B","text":"자신의 영달을 위해 권력의 흐름에 민감하게 반응하는 기회주의적 인물이다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"민족의 비극적 현실을 고뇌하며 지식인으로서의 책무를 다하려 한 인물이다.","vector":{"문장 독해력":-4,"논리 사고력":-4},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"가족을 위해 자신의 신념을 희생할 수밖에 없었던 비운의 가장이다.","vector":{"문장 독해력":-3,"논리 사고력":-3},"error_path":"조건 혼동"},{"choice_id":"E","text":"외세의 침략에 맞서 끝까지 저항 정신을 잃지 않은 의지적 인물이다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q03', 'R1_LIT_P3', 'russell', '어휘단독형', '다음 문장의 빈칸에 들어갈 단어로 적절하지 않은 것은?', '그는 자신의 행동을 (          )하기 위해 갖은 핑계를 댔다.', 'B', '[{"choice_id":"A","text":"옹호","error_path":"부정형 문항 오독: 어휘 의미 혼동","vector":{"어휘력":-5,"문장 독해력":-2}},{"choice_id":"B","text":"강화","error_path":"정답: \'행동을 강화하다\'는 문맥(핑계)과 맞지 않음","vector":{"어휘력":10,"문장 독해력":10}},{"choice_id":"C","text":"변호","error_path":"부정형 문항 오독: 문맥 부적합","vector":{"어휘력":-5,"문장 독해력":-2}},{"choice_id":"D","text":"정당화","error_path":"부정형 문항 오독: 유의어 오해","vector":{"어휘력":-5,"문장 독해력":-2}},{"choice_id":"E","text":"합리화","error_path":"부정형 문항 오독: 어휘 범주 혼동","vector":{"어휘력":-5,"문장 독해력":-2}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q04', 'R1_LIT_P3', 'russell', '어휘단독형', '다음 <보기>의 설명을 바탕으로 할 때, 시어 \'풀섶\'의 표준 발음과 관련된 음운 현상으로 적절한 것은?', '<보기>\n음운의 변동에는 교체, 탈락, 첨가, 축약이 있다. 그중 \'풀섶\'은 [풀섭]으로 발음된다.', 'A', '[{"choice_id":"A","text":"음절의 끝소리 규칙 (교체)","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"ㄴ첨가 (첨가)","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"문법 규칙 오해"},{"choice_id":"C","text":"거센소리되기 (축약)","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"형태소 분석 오류"},{"choice_id":"D","text":"두음 법칙 (교체)","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"품사 판별 오류"},{"choice_id":"E","text":"자음군 단순화 (탈락)","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-4},"error_path":"음운 규칙 오해"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q05', 'R1_LIT_P3', 'russell', '어휘단독형', '다음 <보기>는 훈민정음의 제자 원리에 대한 설명이다. ㉠과 ㉡에 해당하는 글자로 적절하게 짝지어진 것은?', '<보기>\n자음의 기본자는 발음 기관의 모양을 본떠 만들었다(상형). 여기에 획을 하나씩 더하여 소리가 세지는 글자(가획자)를 만들었다.\n- 기본자: ㄱ, ㄴ, ㅁ, ㅅ, ㅇ\n- 가획자 예시: ㉠, ㉡', 'A', '[{"choice_id":"A","text":"㉠: ㅋ, ㉡: ㅌ","vector":{"어법·문법 능력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"㉠: ㄲ, ㉡: ㄸ","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-4},"error_path":"어휘 의미 혼동"},{"choice_id":"C","text":"㉠: ㅁ, ㉡: ㅂ","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"문맥 부적합"},{"choice_id":"D","text":"㉠: ㄹ, ㉡: ㅿ","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"유의어 오해"},{"choice_id":"E","text":"㉠: ㅏ, ㉡: ㅑ","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"어휘 범주 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q06', 'R1_LIT_P3', 'russell', '지문근거형', '(가)의 시어 중 \'공감각적 이미지\'가 사용된 부분으로 가장 적절한 것은?', NULL, 'D', '[{"choice_id":"A","text":"서리 까마귀 우지짖고 지나가는 초라한 지붕","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"지문 근거 누락"},{"choice_id":"B","text":"풀섶 이슬에 함추름 휘적시던 곳","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"세부 정보 오독"},{"choice_id":"C","text":"파아란 하늘빛이 그리워","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"핵심 정보 혼동"},{"choice_id":"D","text":"해설피 금빛 게으른 울음","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"옛이야기 지줄대는 실개천","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"과도한 일반화"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q07', 'R1_LIT_P3', 'russell', '논리추론형', '(나)에서 \'이인국 박사\'가 영어를 사용하고 고려청자를 선물하는 의도로 가장 적절한 것은?', NULL, 'A', '[{"choice_id":"A","text":"새로운 권력인 미국 세력에 밀착하여 자신의 안위를 보장받기 위해","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"미국의 선진 문화를 배워 조국의 발전에 기여하기 위해","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"전제 누락"},{"choice_id":"C","text":"한국의 전통문화를 세계에 널리 알리는 문화사절단이 되기 위해","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"딸의 결혼을 반대하는 마음을 돌려서 사위를 환대하기 위해","vector":{"문장 독해력":-2,"구조 독해력":-2},"error_path":"조건 혼동"},{"choice_id":"E","text":"자신의 과거 친일 행적을 진심으로 반성하고 사과하기 위해","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q08', 'R1_LIT_P3', 'russell', '논리추론형', '(가)의 \'고향\'과 (나)의 \'이인국 박사\'에게 부족한 점을 연결하여 비판할 때 가장 적절한 속담은?', NULL, 'E', '[{"choice_id":"A","text":"개천에서 용 난다 - 어려운 환경에서 훌륭한 사람이 되었다.","vector":{"어휘력":-4,"논리 사고력":-3},"error_path":"전제 누락"},{"choice_id":"B","text":"등잔 밑이 어둡다 - 가까운 곳의 사정을 잘 모른다.","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"수구초심(首丘初心) - 고향을 그리워하는 마음이 없다.","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"조건 혼동"},{"choice_id":"D","text":"초록은 동색 - 끼리끼리 어울린다.","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"범위 과확대"},{"choice_id":"E","text":"감탄고토(甘呑苦吐) - 달면 삼키고 쓰면 뱉는 이기적인 태도","vector":{"어휘력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q09', 'R1_LIT_P3', 'russell', '서술형', '(가)에서 \'청각의 시각화\'가 나타난 구절을 찾아 쓰고, 원관념과 보조관념을 서술하시오.', NULL, NULL, '[]', '해설피 금빛 게으른 울음 / 우는 소리(청각)를 금빛(시각)으로 표현했다.', '[{"condition":"\'해설피 금빛 게으른 울음\'을 찾았는가","score":5,"vector":{"문장 독해력":10},"criteria_id":1},{"condition":"청각을 시각적으로 표현했음을 설명했는가","score":5,"vector":{"국어 개념 적용 능력":10},"criteria_id":2}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P3_Q10', 'R1_LIT_P3', 'russell', '서술형', '(나)에서 \'꺼삐딴 리\'라는 제목이 갖는 반어적 의미를 이인국 박사의 인물 유형과 관련지어 30자 내외로 서술하시오.', NULL, NULL, '[]', '기회주의적인 처세술을 비판하기 위해 그를 우두머리(캡틴)라고 치켜세우는 척하며 조롱하는 의미이다.', '[{"condition":"기회주의적 태도에 대한 비판/풍자를 언급했는가","score":5,"vector":{"논리 사고력":10},"criteria_id":1},{"condition":"반어적 명명(비꼬기, 조롱)임을 이해했는가","score":5,"vector":{"국어 개념 적용 능력":10},"criteria_id":2}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q01', 'R1_LIT_P5', 'russell', '지문근거형', '(가)~(다)에 대한 설명으로 가장 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"(가)와 (나)는 모두 중장과 종장의 길이가 제한 없이 길어진 사설시조이다.","vector":{"구조 독해력":-4,"국어 관련 배경지식":-4},"error_path":"과도한 일반화"},{"choice_id":"B","text":"(다)는 서술자가 개입하지 않고 인물의 대화로만 사건이 전개되는 극 갈래이다.","vector":{"구조 독해력":-3,"국어 관련 배경지식":-3},"error_path":"지문 근거 누락"},{"choice_id":"C","text":"(나)는 구체적인 사물들을 나열하여 화자의 답답한 심정을 해학적으로 표현하고 있다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"(나)와 (다)는 모두 양반 계층의 허위의식을 비판하는 것을 주된 목적으로 한다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"세부 정보 오독"},{"choice_id":"E","text":"(가)와 (다)는 모두 의인화된 동물을 등장시켜 인간 세상을 풍자하고 있다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"핵심 정보 혼동"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q02', 'R1_LIT_P5', 'russell', '논리추론형', '(가)의 \'밤\'과 (다)의 \'간\'에 대한 이해로 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"\'밤\'은 화자가 피하고 싶은 부정적 시간이고, \'간\'은 용왕에게 불필요한 물건이다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"전제 누락"},{"choice_id":"B","text":"\'밤\'은 임의 부재를 상징하고, \'간\'은 용왕의 권위를 상징한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"\'밤\'은 임과 함께하고 싶은 긍정적 시간으로 변용 가능하며, \'간\'은 토끼와 용왕 모두에게 생명과 직결된 중요한 대상이다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"\'밤\'과 \'간\'은 모두 현실에서 존재하지 않는 환상적인 소재이다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"조건 혼동"},{"choice_id":"E","text":"\'밤\'은 절대적인 길이를 가진 물리적 시간이고, \'간\'은 토끼가 숨길 수 있는 물리적 신체 부위이다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q03', 'R1_LIT_P5', 'russell', '어휘단독형', '(다)의 밑줄 친 \'미련하다\'와 문맥적 의미가 가장 유사한 것은?', '네가 이리 **미련하단** 말이냐?', 'C', '[{"choice_id":"A","text":"지난 일에 **미련** 갖지 마라.","vector":{"어휘력":-3,"문장 독해력":-3},"error_path":"어휘 의미 혼동"},{"choice_id":"B","text":"그는 옛사랑에 **미련**이 남았다.","vector":{"어휘력":-3,"문장 독해력":-3},"error_path":"문맥 부적합"},{"choice_id":"C","text":"그 사람은 곰처럼 **미련해서** 눈치라곤 없다.","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"D","text":"아직도 **미련**을 버리지 못했니?","vector":{"어휘력":-3,"문장 독해력":-3},"error_path":"유의어 오해"},{"choice_id":"E","text":"떠나는 마당에 무슨 **미련**을 두느냐","vector":{"어휘력":-3,"문장 독해력":-3},"error_path":"어휘 범주 혼동"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q04', 'R1_LIT_P5', 'russell', '어휘단독형', '다음 <보기>의 단어에서 일어나는 음운 변동 현상으로 적절한 것은?', '<보기>\n**동짓달** [동/짇/딸]', 'D', '[{"choice_id":"A","text":"구개음화, 음절의 끝소리 규칙","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"문법 규칙 오해"},{"choice_id":"B","text":"음절의 끝소리 규칙, 비음화","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"형태소 분석 오류"},{"choice_id":"C","text":"자음군 단순화, 된소리되기","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-4},"error_path":"품사 판별 오류"},{"choice_id":"D","text":"음절의 끝소리 규칙, 된소리되기","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"유음화, 된소리되기","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"음운 규칙 오해"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q05', 'R1_LIT_P5', 'russell', '어휘단독형', '다음 <보기>의 밑줄 친 문장의 짜임에 대한 설명으로 적절한 것은?', '<보기>\n이것은 **우리가 먹을** 사과다.', 'D', '[{"choice_id":"A","text":"서술절을 안은문장","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"어휘 의미 혼동"},{"choice_id":"B","text":"부사절을 안은문장","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"문맥 부적합"},{"choice_id":"C","text":"인용절을 안은문장","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"유의어 오해"},{"choice_id":"D","text":"관형절을 안은문장","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"명사절을 안은문장","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3},"error_path":"어휘 범주 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q06', 'R1_LIT_P5', 'russell', '지문근거형', '(가)에서 \'추상적 개념의 구체화\'가 가장 잘 드러난 구절은?', NULL, 'C', '[{"choice_id":"A","text":"춘풍 니불 아레","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"지문 근거 누락"},{"choice_id":"B","text":"어론 님 오신 날","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"세부 정보 오독"},{"choice_id":"C","text":"한 허리를 버혀 내여","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"D","text":"동짓달 기나긴 밤","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"핵심 정보 혼동"},{"choice_id":"E","text":"구뷔구뷔 펴리라","vector":{"문장 독해력":-3,"국어 개념 적용 능력":-2},"error_path":"과도한 일반화"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q07', 'R1_LIT_P5', 'russell', '논리추론형', '(다)의 \'용왕\'의 태도로 가장 적절한 것은?', NULL, 'E', '[{"choice_id":"A","text":"신하들의 반대에도 불구하고 독단적으로 결정을 내리는 카리스마를 보여준다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"전제 누락"},{"choice_id":"B","text":"자신의 권력을 이용해 약자를 무조건 힘으로 억누르려는 폭력성을 보인다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"상대방의 뛰어난 언변과 지혜를 인정하고 겸손하게 배움을 청하고 있다.","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"조건 혼동"},{"choice_id":"D","text":"상대방의 거짓말을 이미 알고 있지만 재미를 위해 모른 척하고 있다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"범위 과확대"},{"choice_id":"E","text":"상대방의 말을 의심하면서도 자신의 병을 고치려는 욕심 때문에 속아 넘어가고 있다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q08', 'R1_LIT_P5', 'russell', '논리추론형', '다음은 (가)에 대한 평론이다. 빈칸에 들어갈 한자 성어로 가장 적절한 것은?', '황진이는 임을 기다리는 간절한 마음을 (          )이라는 말처럼, 하루가 천 년 같은 긴 시간으로 느끼며 절절하게 표현하고 있다.', 'B', '[{"choice_id":"A","text":"사면초가(四面楚歌)","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"전제 누락"},{"choice_id":"B","text":"일각여삼추(一刻如三秋)","vector":{"어휘력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"동병상련(同病相憐)","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"오비이락(烏飛梨落)","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"조건 혼동"},{"choice_id":"E","text":"전화위복(轉禍爲福)","vector":{"어휘력":-3,"논리 사고력":-2},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q09', 'R1_LIT_P5', 'russell', '서술형', '(나)에서 자신의 답답한 심정을 해소하고 싶은 소망을 드러내기 위해 사용한 매개체가 무엇인지 쓰시오.', NULL, NULL, '[]', '창 (또는 창문)', '[{"condition":"\'창\' 혹은 \'창문\'을 썼는가","score":5,"vector":{"문장 독해력":10},"criteria_id":1},{"condition":"가슴에 내고 싶다는 맥락을 이해했는가","score":5,"vector":{"국어 관련 배경지식":10},"criteria_id":2}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_LIT_P5_Q10', 'R1_LIT_P5', 'russell', '서술형', '(다)에서 토끼가 용왕을 속이기 위해 내세운 논리를 30자 내외로 서술하시오.', NULL, NULL, '[]', '간은 귀한 보화라 뱃속에 넣으면 썩거나 잃어버릴 수 있어 육지에 따로 보관해 두었다.', '[{"condition":"간을 육지에 두고 왔다는 핵심 거짓말을 서술했는가","score":5,"vector":{"문장 독해력":10},"criteria_id":1},{"condition":"그럴듯한 이유(보화, 썩음 등)를 포함했는가","score":5,"vector":{"논리 사고력":10},"criteria_id":2}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q01', 'R1_NON_P3', 'russell', '지문근거형', '윗글의 내용과 일치하는 것은?', NULL, 'B', '[{"choice_id":"A","text":"물권과 채권이 충돌하면 원칙적으로 채권이 우선한다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 근거 누락"},{"choice_id":"B","text":"소유권은 물건을 배타적으로 지배할 수 있는 대표적인 물권이다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"채권은 모든 사람에게 주장할 수 있는 절대적인 권리이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"과도한 일반화"},{"choice_id":"D","text":"물권은 특정한 사람에게 어떤 행위를 요구하는 권리이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"세부 정보 오독"},{"choice_id":"E","text":"채권자 대위권은 채무자의 재산이 넉넉할 때만 행사할 수 있다.","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"핵심 정보 혼동"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q02', 'R1_NON_P3', 'russell', '논리추론형', '윗글을 바탕으로 <보기>의 상황을 판단한 내용으로 적절하지 않은 것은?', '<보기>\n철수는 영희에게 100만 원을 빌려주었다(채권). 영희는 갚을 돈이 없다고 버티고 있지만, 사실 영희는 민수에게 받을 돈 200만 원이 있다. 그런데도 영희는 민수에게 돈을 달라고 하지 않고 있다.', 'A', '[{"choice_id":"A","text":"철수는 직접 민수에게 찾아가 \'내 돈 100만 원을 내놓으라\'고 강제로 빼앗을 수 있는 물권이 있다.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"영희는 민수에게 돈을 받을 권리, 즉 채권을 가지고 있다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 전제 누락"},{"choice_id":"C","text":"영희가 권리를 행사하지 않으므로 철수는 영희를 대신해 민수에게 돈을 청구할 수 있는 \'채권자 대위권\'을 고려할 수 있다.","vector":{"논리 사고력":-5,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 인과 관계 왜곡"},{"choice_id":"D","text":"철수는 영희에게 돈을 갚으라고 요구할 수 있는 채권자이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 조건 혼동"},{"choice_id":"E","text":"철수의 채권은 영희라는 특정한 사람에게만 행사하는 것이 원칙이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 범위 과확대"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q03', 'R1_NON_P3', 'russell', '어휘단독형', '다음 문장의 빈칸에 들어갈 단어로 가장 적절한 것은?', '그는 자신의 권리를 (          )으로 행사했다.', 'B', '[{"choice_id":"A","text":"보편적","error_path":"의미 불일치","vector":{"어휘력":-3,"문장 독해력":-2}},{"choice_id":"B","text":"배타적","error_path":"정답","vector":{"어휘력":10,"문장 독해력":10}},{"choice_id":"C","text":"의존적","error_path":"의미 불일치 (1)","vector":{"어휘력":-3,"문장 독해력":-2}},{"choice_id":"D","text":"상대적","error_path":"개념 혼동 (배타적 의미를 상대적 의미로 오해)","vector":{"어휘력":-2,"문장 독해력":-2}},{"choice_id":"E","text":"이타적","error_path":"반의어 관계(남을 위함)","vector":{"어휘력":-3,"문장 독해력":-3}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q04', 'R1_NON_P3', 'russell', '어휘단독형', '다음 <보기>의 단어들을 \'조음 위치\'에 따라 분류할 때, 이질적인 하나는?', '<보기>\n① **권**리\n② **경**우\n③ **균**형\n④ **관**계\n⑤ **도**로', 'A', '[{"choice_id":"A","text":"도 (ㄷ, 잇몸소리)","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"권 (ㄱ, 연구개음)","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-2},"error_path":"어휘 의미 혼동"},{"choice_id":"C","text":"관 (ㄱ, 연구개음)","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-2},"error_path":"문맥 부적합"},{"choice_id":"D","text":"경 (ㄱ, 연구개음)","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-2},"error_path":"유의어 오해"},{"choice_id":"E","text":"균 (ㄱ, 연구개음)","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-2},"error_path":"어휘 범주 혼동"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q05', 'R1_NON_P3', 'russell', '어휘단독형', '다음 <보기>의 설명을 참고할 때, \'가획의 원리\'에 의해 만들어진 글자가 아닌 것은?', '<보기>\n훈민정음 자음의 기본자(ㄱ, ㄴ, ㅁ, ㅅ, ㅇ)에 획을 더하여 소리의 세기를 나타낸 글자를 가획자라고 한다.', 'D', '[{"choice_id":"A","text":"ㄷ (ㄴ에 가획)","vector":{"어법·문법 능력":-5,"국어 관련 배경지식":-2},"error_path":"부정형 문항 오독: 어휘 의미 혼동"},{"choice_id":"B","text":"ㅊ (ㅈ에 가획)","vector":{"어법·문법 능력":-5,"국어 관련 배경지식":-2},"error_path":"부정형 문항 오독: 문맥 부적합"},{"choice_id":"C","text":"ㅋ (ㄱ에 가획)","vector":{"어법·문법 능력":-5,"국어 관련 배경지식":-2},"error_path":"부정형 문항 오독: 유의어 오해"},{"choice_id":"D","text":"ㄹ (이체자)","vector":{"어법·문법 능력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"E","text":"ㅍ (ㅁ에서 ㅂ, 다시 ㅍ으로 가획 계열)","vector":{"어법·문법 능력":-5,"국어 관련 배경지식":-2},"error_path":"부정형 문항 오독: 어휘 범주 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q06', 'R1_NON_P3', 'russell', '지문근거형', '윗글에서 \'물권\'의 특성으로 언급되지 않은 것은?', NULL, 'B', '[{"choice_id":"A","text":"우선성(물권 우선주의)","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"B","text":"상대성","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"절대성","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 과도한 일반화"},{"choice_id":"D","text":"직접 지배성","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"E","text":"배타성","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 핵심 정보 혼동"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q07', 'R1_NON_P3', 'russell', '논리추론형', '윗글을 통해 알 수 있는 사실은?', NULL, 'B', '[{"choice_id":"A","text":"소유권은 특정한 사람에게만 주장할 수 있는 권리이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"전제 누락"},{"choice_id":"B","text":"등기는 채권을 물권처럼 강력하게 보호하기 위한 수단이 될 수 있다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"임차권은 대표적인 물권의 일종이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"채권자는 채무자의 동의 없이는 어떤 경우에도 채무자의 권리를 대신 행사할 수 없다.","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"조건 혼동"},{"choice_id":"E","text":"물권은 당사자 간의 계약으로 자유롭게 새로운 종류를 만들 수 있다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q08', 'R1_NON_P3', 'russell', '논리추론형', '다음 중 \'채권\'의 성격에 가장 가까운 예시는?', NULL, 'A', '[{"choice_id":"A","text":"헬스장 관장님에게 환불을 요구했다.","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"주운 지갑의 주인을 찾아 돌려주었다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"전제 누락"},{"choice_id":"C","text":"서점에서 책을 사서 내 책장에 꽂아 두었다.","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"내가 산 노트북을 중고 장터에 팔았다.","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"조건 혼동"},{"choice_id":"E","text":"내 밭에 옥수수를 심어 수확했다.","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q09', 'R1_NON_P3', 'russell', '서술형', '윗글을 바탕으로, 물권이 채권보다 강력한 권리로 취급받는 이유인 \'누구에게나 자신의 권리를 주장할 수 있는 성질\'을 가리키는 3음절 단어를 쓰시오.', NULL, NULL, '[]', '절대권 (또는 배타성)', '[{"condition":"\'절대권\'을 썼는가","score":5,"vector":{"어휘력":10},"criteria_id":1},{"condition":"또는 \'배타성\'(배타적 권리)을 썼는가","score":5,"vector":{"문장 독해력":10},"criteria_id":2}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P3_Q10', 'R1_NON_P3', 'russell', '서술형', '윗글을 바탕으로 \'채권자 대위권\'이 필요한 이유를 30자 내외로 서술하시오.', NULL, NULL, '[]', '채무자가 권리를 행사하지 않아 채권자가 돈을 떼일 위험을 막기 위해서이다.', '[{"condition":"채무자의 권리 불행사를 언급했는가","score":5,"vector":{"문장 독해력":10},"criteria_id":1},{"condition":"채권 보호의 필요성을 서술했는가","score":5,"vector":{"논리 사고력":10},"criteria_id":2}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q01', 'R1_NON_P5', 'russell', '지문근거형', '윗글의 내용과 일치하지 않는 것은?', NULL, 'E', '[{"choice_id":"A","text":"연역법은 새로운 지식을 크게 확장하는 데에는 한계가 있을 수 있다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"B","text":"귀납법은 단 하나의 반례만 있어도 결론이 거짓이 될 수 있다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"C","text":"연역법은 일반적인 원리에서 구체적인 사실을 이끌어낸다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"D","text":"추론은 논리적인 근거를 들어 설명하는 과정이다.","vector":{"문장 독해력":-5,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 과도한 일반화"},{"choice_id":"E","text":"귀납법은 전제가 참이면 결론도 항상 반드시 참이 된다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q02', 'R1_NON_P5', 'russell', '논리추론형', '윗글을 바탕으로 <보기>의 추론 방식을 판단할 때 적절한 것은?', '<보기>\nA: 까마귀는 날 수 있다.\nB: 독수리도 날 수 있다.\nC: 참새도 날 수 있다.\n결론: 그러므로 모든 새는 날 수 있다.', 'D', '[{"choice_id":"A","text":"연역법이며, 결론은 필연적으로 참이다.","vector":{"논리 사고력":-5,"비문학 배경지식":-4},"error_path":"전제 누락"},{"choice_id":"B","text":"귀납법이며, 많은 사례를 관찰했으므로 결론은 반드시 참이다.","vector":{"논리 사고력":-4,"비문학 배경지식":-3},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"연역법과 귀납법이 혼합된 방식이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"조건 혼동"},{"choice_id":"D","text":"귀납법이며, 펭귄이나 타조 같은 반례가 있으므로 결론이 틀릴 수 있다.","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"연역법이며, 대전제가 잘못되었으므로 결론도 거짓이다.","vector":{"논리 사고력":-5,"비문학 배경지식":-4},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q03', 'R1_NON_P5', 'russell', '어휘단독형', '다음 문장의 빈칸에 들어갈 단어로 가장 적절한 것은?', '귀납법은 결론이 참일 (          )이 높을 뿐이다.', 'C', '[{"choice_id":"A","text":"우연성","error_path":"반대 의미에 가까움","vector":{"어휘력":-3,"문장 독해력":-2}},{"choice_id":"B","text":"당위성","error_path":"의미 불일치","vector":{"어휘력":-3,"문장 독해력":-2}},{"choice_id":"C","text":"개연성","error_path":"정답","vector":{"어휘력":10,"문장 독해력":10}},{"choice_id":"D","text":"특수성","error_path":"의미 불일치 (1)","vector":{"어휘력":-3,"문장 독해력":-2}},{"choice_id":"E","text":"필연성","error_path":"연역법의 특징","vector":{"어휘력":-3,"문장 독해력":-3}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q04', 'R1_NON_P5', 'russell', '어휘단독형', '다음 <보기>의 밑줄 친 단어에서 일어나는 음운 변동에 대한 설명으로 옳은 것은?', '<보기>\n연역법의 **법칙**[법칙]은 중요하다.\n이 **백조**[백쪼]는 하얗다.', 'B', '[{"choice_id":"A","text":"\'백조\'는 모음 사이에서 된소리가 되므로 사잇소리 현상에 해당한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"문법 규칙 오해"},{"choice_id":"B","text":"\'백조\'의 \'ㄱ\' 받침 뒤에서 \'ㅈ\'이 된소리 [ㅉ]으로 발음되므로 된소리되기(교체)이다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"C","text":"\'법칙\'과 \'백조\' 모두 음절의 끝소리 규칙이 적용되었다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"형태소 분석 오류"},{"choice_id":"D","text":"\'법칙\'은 원래 된소리로 발음되므로 음운 변동이 아니다.","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-4},"error_path":"품사 판별 오류"},{"choice_id":"E","text":"\'법칙\'의 \'ㅂ\' 받침 뒤에서 \'ㅊ\'이 거센소리 [ㅊ]으로 발음되므로 축약이다.","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"음운 규칙 오해"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q05', 'R1_NON_P5', 'russell', '어휘단독형', '다음 <보기>의 문장에서 \'안긴문장\'의 종류와 기능이 올바르게 연결된 것은?', '<보기>\n우리는 **그 말이 사실임**을 알았다.', 'D', '[{"choice_id":"A","text":"관형절 - 주어 역할","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"어휘 의미 혼동"},{"choice_id":"B","text":"명사절 - 주어 역할","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"문맥 부적합"},{"choice_id":"C","text":"부사절 - 부사어 역할","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"유의어 오해"},{"choice_id":"D","text":"명사절 - 목적어 역할","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"관형절 - 목적어 역할","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"어휘 범주 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q06', 'R1_NON_P5', 'russell', '지문근거형', '윗글을 통해 \'연역법\'의 한계점으로 지적할 수 있는 것은?', NULL, 'A', '[{"choice_id":"A","text":"전제 속에 이미 결론이 포함되어 있어 새로운 지식 확장에 제한적이다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"결론이 필연적으로 참이 아닐 수 있다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"지문 근거 누락"},{"choice_id":"C","text":"많은 사례를 관찰해야 하는 번거로움이 있다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"세부 정보 오독"},{"choice_id":"D","text":"과학적 탐구 방법으로 사용하기에는 부적절하다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"핵심 정보 혼동"},{"choice_id":"E","text":"개별적인 사실들로부터 공통점을 찾아내기가 어렵다.","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"과도한 일반화"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q07', 'R1_NON_P5', 'russell', '논리추론형', '윗글의 \'검은 백조(블랙 스완)\'가 의미하는 바로 가장 적절한 것은?', NULL, 'E', '[{"choice_id":"A","text":"연역법의 대전제가 절대적으로 옳음을 증명하는 사례","vector":{"문장 독해력":-5,"논리 사고력":-4},"error_path":"전제 누락"},{"choice_id":"B","text":"자연의 신비와 아름다움을 상징하는 희귀한 동물","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"과학 기술의 발달로 인해 새롭게 탄생한 생명체","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"조건 혼동"},{"choice_id":"D","text":"인류의 지식이 더 이상 발전할 수 없음을 나타내는 한계","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"범위 과확대"},{"choice_id":"E","text":"귀납적 결론이 언제든지 거짓이 될 수 있음을 보여주는 반례","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q08', 'R1_NON_P5', 'russell', '논리추론형', '다음 중 성격이 다른 하나는?', NULL, 'B', '[{"choice_id":"A","text":"제주도의 까마귀는 검다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"전제 누락"},{"choice_id":"B","text":"모든 지역의 까마귀는 검다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"부산의 까마귀는 검다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"인과 관계 왜곡"},{"choice_id":"D","text":"강원도의 까마귀는 검다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"조건 혼동"},{"choice_id":"E","text":"서울의 까마귀는 검다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"범위 과확대"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q09', 'R1_NON_P5', 'russell', '서술형', '윗글에서 설명한 \'연역법\'과 \'귀납법\' 중 전제가 참일 때 결론도 반드시 참이 되는 추론 방식을 쓰시오.', NULL, NULL, '[]', '연역법', '[{"condition":"\'연역법\'을 정확히 썼는가","score":5,"vector":{"문장 독해력":10},"criteria_id":1},{"condition":"오탈자 없는가","score":5,"vector":{"어휘력":10},"criteria_id":2}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('R1_NON_P5_Q10', 'R1_NON_P5', 'russell', '서술형', '윗글을 바탕으로, 귀납법의 결론이 100% 확실하지 않은 이유를 \'반례\'라는 단어를 사용하여 30자 내외로 서술하시오.', NULL, NULL, '[]', '단 하나의 반례만 나타나도 그 결론이 거짓이 될 수 있기 때문이다.', '[{"condition":"\'반례\'라는 단어를 포함했는가","score":5,"vector":{"어휘력":10},"criteria_id":1},{"condition":"반례로 인해 결론이 뒤집힐 가능성을 서술했는가","score":5,"vector":{"논리 사고력":10},"criteria_id":2}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q01', 'W1_LIT_P3', 'wittgenstein', '지문근거형', '(가)와 (나)의 공통점으로 가장 적절한 것은?', NULL, 'A', '[{"choice_id":"A","text":"화자(또는 서술자)의 정서를 자연물에 의탁하여 표현하고 있다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"대화 형식을 통해 인물 간의 갈등 해소 과정을 보여주고 있다.","vector":{"문장 독해력":-3,"구조 독해력":-2},"error_path":"형식적 특징 오류"},{"choice_id":"C","text":"부정적 현실을 비판하며 사회 개혁의 의지를 드러내고 있다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"주제 파악 오류"},{"choice_id":"D","text":"현실의 고통을 잊기 위해 초월적 세계로의 도피를 꿈꾸고 있다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"작품 감상 오류"},{"choice_id":"E","text":"계절의 변화에 따라 시상을 전개하며 인생의 무상함을 강조하고 있다.","vector":{"문장 독해력":-3,"구조 독해력":-2},"error_path":"전개 방식 오류"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q02', 'W1_LIT_P3', 'wittgenstein', '논리추론형', '(가)의 \'새\'와 (나)의 \'기러기\'에 대한 설명으로 가장 적절한 것은?', NULL, 'D', '[{"choice_id":"A","text":"\'새\'와 \'기러기\'는 모두 화자가 지향하는 자유로운 삶을 상징한다.","vector":{"국어 관련 배경지식":-3,"논리 사고력":-2},"error_path":"상징적 의미 파악 오류"},{"choice_id":"B","text":"\'새\'는 화자의 분신으로서 현실 도피처를 안내하고, \'기러기\'는 화자와 낭군을 이어주는 매개체 역할을 한다.","vector":{"국어 관련 배경지식":-4,"논리 사고력":-3},"error_path":"소재 기능 파악 오류"},{"choice_id":"C","text":"\'새\'는 화자에게 위로를 주는 존재이고, \'기러기\'는 화자의 앞날을 예언하는 존재이다.","vector":{"국어 관련 배경지식":-3,"논리 사고력":-2},"error_path":"소재 의미 파악 오류 (1)"},{"choice_id":"D","text":"\'새\'는 화자의 감정이 이입된 대상이고, \'기러기\'는 화자의 슬픔을 심화시키는 객관적 상관물이다.","vector":{"국어 관련 배경지식":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"E","text":"\'새\'는 화자와 대조되는 처지의 대상이고, \'기러기\'는 화자의 동경의 대상이다.","vector":{"국어 관련 배경지식":-3,"논리 사고력":-2},"error_path":"소재 의미 파악 오류"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q03', 'W1_LIT_P3', 'wittgenstein', '어휘단독형', '다음 <보기>의 설명을 참고할 때, ⓐ와 바꿔 쓰기에 가장 적절한 한자어는?', '<보기>\n**보전(保全)**: 온전하게 보호하여 유지함.\n**보존(保存)**: 잘 보호하고 간수하여 남김.', 'D', '[{"choice_id":"A","text":"유지(維持)","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"유의어 혼동 (1)"},{"choice_id":"B","text":"건사(健事)","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"유의어 혼동 (2)"},{"choice_id":"C","text":"수호(守護)","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"유의어 혼동 (3)"},{"choice_id":"D","text":"보존(保存)","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"E","text":"보위(保衛)","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"유의어 혼동"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q04', 'W1_LIT_P3', 'wittgenstein', '어휘단독형', '다음 <보기>의 밑줄 친 부분 중 \'한글 맞춤법\'에 어긋난 것은?', '<보기>\n① 그는 나를 보자마자 **멋쩍게** 웃었다.\n② 시험에 합격할 수 있을지 **자신이 없다**. \n③ 며칠 밤을 새워 공부했더니 **눈곱**이 끼었다.\n④ 김치찌개를 끓일 때는 돼지고기를 **널찍하게** 썰어 넣어야 맛있다.\n⑤ 친구와 싸운 뒤 화해하려고 먼저 **알은체**를 했다.', 'E', '[{"choice_id":"A","text":"② 자신이 없다","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"맞춤법 오해 (1)"},{"choice_id":"B","text":"③ 눈곱","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"맞춤법 오해 (2)"},{"choice_id":"C","text":"① 멋쩍게","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"맞춤법 오해"},{"choice_id":"D","text":"④ 널찍하게","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"맞춤법 오해 (3)"},{"choice_id":"E","text":"⑤ 알은체","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q05', 'W1_LIT_P3', 'wittgenstein', '어휘단독형', '(가)의 밑줄 친 \'살어리랏다\'에 대한 중세 국어 문법적 설명으로 적절한 것은?', '<보기>\n고려 가요 \'청산별곡\'은 문자로 정착되기 전 오랫동안 구전되다가 훈민정음 창제 이후 문헌(악장가사 등)에 기록되었다.', 'B', '[{"choice_id":"A","text":"주로 평서문에서 사용되는 종결 어미 \'-다\'가 쓰여 단순히 사실을 진술하고 있다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"어미 기능 파악 오류"},{"choice_id":"B","text":"\'살-(어근) + -어리(접미사) + -랏다(어미)\'의 구조로, \'살고 싶어라\' 정도의 소망을 나타낸다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"C","text":"\'살-(어근) + -어(연결 어미) + -리(미래 시제) + -랏다(종결 어미)\'로 분석된다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"형태소 분석 오류 (1)"},{"choice_id":"D","text":"\'ㄹ\' 받침 뒤에서 매개 모음 \'으\'가 생략된 형태로, 현대 국어의 표기법과 일치한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"음운 규칙 설명 오류"},{"choice_id":"E","text":"\'살-\'(Live)에 시제 선어말 어미 \'-었-\'이 결합된 형태이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"형태소 분석 오류"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q06', 'W1_LIT_P3', 'wittgenstein', '논리추론형', '(가)의 화자가 현실을 대하는 태도의 변화 과정을 바르게 나열한 것은?', NULL, 'A', '[{"choice_id":"A","text":"현실 도피(청산) → 비애의 심화 → 현실 도피(바다) → 일시적 해소(술)","vector":{"구조 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"현실 비판 → 이상향 동경 → 현실 타협 → 운명 수용","vector":{"구조 독해력":-3,"국어 관련 배경지식":-2},"error_path":"시상 전개 파악 오류"},{"choice_id":"C","text":"개인적 고뇌 → 사회적 모순 인식 → 집단적 저항 → 이상적 세계 실현","vector":{"구조 독해력":-3,"국어 관련 배경지식":-2},"error_path":"태도 분석 오류 (2)"},{"choice_id":"D","text":"자연 친화 → 속세에 대한 미련 → 고독감 토로 → 현실 극복 의지","vector":{"구조 독해력":-4,"국어 관련 배경지식":-3},"error_path":"태도 분석 오류"},{"choice_id":"E","text":"현실 부정 → 이상향 모색 → 좌절과 체념 → 미래에 대한 희망","vector":{"구조 독해력":-3,"국어 관련 배경지식":-2},"error_path":"태도 분석 오류 (1)"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q07', 'W1_LIT_P3', 'wittgenstein', '논리추론형', '(나)에서 운영이 편지를 통해 전달하고자 하는 핵심 내용으로 가장 적절한 것은?', NULL, 'E', '[{"choice_id":"A","text":"자신의 처지를 비관하며 김 진사에게 이별을 통보한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"의도 파악 오류"},{"choice_id":"B","text":"자신의 시를 칭찬해 준 김 진사에게 문학적 조언을 구한다.","vector":{"문장 독해력":-2,"논리 사고력":-2},"error_path":"지엽적 정보 과대 해석"},{"choice_id":"C","text":"안평대군의 엄격한 감시를 피해 자신을 구출해 달라고 호소한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"내용 왜곡 (1)"},{"choice_id":"D","text":"김 진사와의 사랑을 위해 함께 도망칠 계획을 제안한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"내용 왜곡"},{"choice_id":"E","text":"현세에서의 만남이 어려움을 토로하며 후생의 기약을 당부한다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q08', 'W1_LIT_P3', 'wittgenstein', '논리추론형', '(가)의 \'술\'과 (나)의 \'편지\'가 갖는 공통적인 문학적 기능은?', NULL, 'D', '[{"choice_id":"A","text":"사회적 모순을 고발하고 저항 의지를 고취시키는 수단이다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"기능 파악 오류 (1)"},{"choice_id":"B","text":"화자와 청자 사이의 단절된 관계를 영구적으로 확인시켜 준다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"기능 파악 오류 (3)"},{"choice_id":"C","text":"과거 회상을 통해 행복했던 시절을 떠올리게 하는 소재이다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"기능 파악 오류 (2)"},{"choice_id":"D","text":"화자의 정서를 일시적으로나마 해소하거나 전달하는 매개체이다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"E","text":"화자의 내적 갈등을 유발하는 원인이다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"기능 파악 오류"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q09', 'W1_LIT_P3', 'wittgenstein', '서술형', '(가)에서 \'돌\'을 맞아서 운다고 표현한 화자의 심정을 한 문장으로 서술하시오. (30자 내외)', NULL, NULL, '[]', '피할 수 없는 운명적 비애와 이유 없는 고통에 대한 체념적 태도를 보인다.', '[{"criteria_id":1,"condition":"\'운명적\' 혹은 \'피할 수 없는\' 의미 포함","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"\'체념\' 혹은 \'비애(슬픔)\' 내용 포함","score":5,"vector":{"국어 관련 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P3_Q10', 'W1_LIT_P3', 'wittgenstein', '서술형', '(나)에서 운영이 김 진사와의 사랑을 이루기 어렵다고 판단하는 현실적 제약 두 가지를 본문에서 찾아 서술하시오. (30자 내외)', NULL, NULL, '[]', '대군의 엄한 명령(궁중 법도)과 주위의 시기 및 질투.', '[{"criteria_id":1,"condition":"\'대군의 명령\' 혹은 \'엄명\', \'법도\' 언급","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"\'시기\', \'질투\', \'주변의 눈/귀\' 언급","score":5,"vector":{"문장 독해력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q01', 'W1_LIT_P5', 'wittgenstein', '지문근거형', '(가)와 (나)에 대한 설명으로 가장 적절한 것은?', NULL, 'B', '[{"choice_id":"A","text":"(가)는 과거와 현재를 교차하여, (나)는 공간의 이동을 통해 인물의 심리 변화를 보여준다.","vector":{"문장 독해력":-3,"구조 독해력":-2},"error_path":"전개 방식 분석 오류"},{"choice_id":"B","text":"(가)는 자연물의 속성을 통해, (나)는 인물의 행위와 대화를 통해 주제 의식을 드러낸다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"(가)는 화자의 내면 독백을 중심으로, (나)는 서술자의 직접 개입을 중심으로 사건을 전달한다.","vector":{"문장 독해력":-3,"구조 독해력":-2},"error_path":"서술 시점 분석 오류"},{"choice_id":"D","text":"(가)는 감각적 이미지를 활용하여 자연 친화적 태도를, (나)는 향토적 소재를 활용하여 공동체적 유대감을 강조한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"주제 파악 오류"},{"choice_id":"E","text":"(가)와 (나)는 모두 이상적인 세계에 대한 동경과 현실의 좌절감을 대비시키고 있다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"정서 파악 오류"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q02', 'W1_LIT_P5', 'wittgenstein', '논리추론형', '(가)의 \'사랑의 연습\'과 (나)의 \'소리의 완성\'에 대한 이해로 가장 적절한 것은?', NULL, 'A', '[{"choice_id":"A","text":"\'사랑의 연습\'은 끊임없이 반복되는 자연의 순환적 속성을, \'소리의 완성\'은 고통과 희생을 통해 도달하는 예술적 경지를 의미한다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"\'사랑의 연습\'은 미완성의 상태에 머무르는 안타까움을, \'소리의 완성\'은 인위적으로 도달할 수 있는 경지를 의미한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"시어 의미 오해"},{"choice_id":"C","text":"\'사랑의 연습\'은 화자가 지향하는 이상적 삶을, \'소리의 완성\'은 유봉이 송화에게 강요하는 세속적 성공을 의미한다.","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"가치관 판단 오류"},{"choice_id":"D","text":"\'사랑의 연습\'은 대상과의 합일을, \'소리의 완성\'은 대상과의 영원한 결별을 전제로 한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"개념 관계 오해"},{"choice_id":"E","text":"\'사랑의 연습\'과 \'소리의 완성\'은 모두 현실의 고통을 잊기 위한 도피처로서의 기능을 한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"기능 파악 오류"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q03', 'W1_LIT_P5', 'wittgenstein', '어휘단독형', '문맥상 ⓐ~ⓔ의 단어와 바꿔 쓰기에 적절하지 않은 것은?', 'ⓐ 윤이 나고 (빛이 나서 반짝이다)\nⓑ 뇌까리고 (불만스러운 말투로 계속 말하다)\nⓒ 의지(依支)해 (다른 것에 몸을 기대다)\nⓓ 여의 어서 (죽어서 이별하다)\nⓔ 애절(哀切)했다 (몹시 슬프다)', 'B', '[{"choice_id":"A","text":"ⓒ: 기대로","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 의미 혼동"},{"choice_id":"B","text":"ⓑ: 되뇌고","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"ⓐ: 반짝이고","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 문맥 부적합"},{"choice_id":"D","text":"ⓓ: 사별하고","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 유의어 오해"},{"choice_id":"E","text":"ⓔ: 비통했다","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 범주 혼동"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q04', 'W1_LIT_P5', 'wittgenstein', '어휘단독형', '다음 <보기>의 밑줄 친 부분에 대한 문법적 설명으로 적절하지 않은 것은?', '<보기>\n① 나를 **버리고** 나간 것\n② 송화는 누구를 **의지해** 살아가겠느냐\n③ 내 자식의 눈을 멀게 **해서라도**\n④ 깊은 곳에서 **우러나오는** 그 무엇\n⑤ **잠에서** 깨어난 여인', 'B', '[{"choice_id":"A","text":"③: \'해서라도\'는 \'하- + -아서 + -라도\'의 결합으로 분석할 수 있다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 문법 규칙 오해"},{"choice_id":"B","text":"①: \'버리고\'는 종결 어미 \'-고\'가 쓰여 문장을 끝내고 있다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"C","text":"⑤: \'잠에서\'의 \'에서\'는 부사격 조사로, 출발점이나 유래의 의미를 지닌다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 형태소 분석 오류"},{"choice_id":"D","text":"②: \'의지해\'는 \'의지하-\'에 어미 \'-여\'가 결합하여 \'의지하여\'가 된 후 줄어든 형태이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 품사 판별 오류"},{"choice_id":"E","text":"④: \'우러나오는\'은 동사 \'우러나오다\'의 관형사형으로 뒤에 오는 명사를 수식한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 음운 규칙 오해"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q05', 'W1_LIT_P5', 'wittgenstein', '어휘단독형', '다음 <보기>는 (나)의 문장들을 문법적으로 분석한 것이다. 적절하지 않은 것은?', '<보기>\nㄱ. 아비는 송화 누이의 눈을 멀게 했다.\nㄴ. 소리의 완성을 위해서 가슴에 한을 심어 주고 싶었다.\nㄷ. 너는 내 자식이 아니었으니 나를 버리고 나간 것은 나무랄 일이 아니었다.', 'D', '[{"choice_id":"A","text":"ㄷ: \'아니었으니\'는 연결 어미 \'-으니\'를 사용하여 인과 관계를 나타내고 있다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 문법 규칙 오해"},{"choice_id":"B","text":"ㄱ, ㄴ, ㄷ 모두 서술어의 자릿수를 채우기 위해 목적어가 필요한 문장이 포함되어 있다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 형태소 분석 오류"},{"choice_id":"C","text":"ㄱ: \'눈을 멀게 했다\'는 주동문을 사동문으로 바꾼 형태이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 품사 판별 오류"},{"choice_id":"D","text":"ㄷ: \'나무랄 일이 아니었다\'에서 \'나무랄\'은 관형사형 어미 \'-ㄹ\'이 붙어 미래 시제를 나타낸다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"ㄴ: \'심어 주고 싶었다\'에는 본용언 \'심다\'와 보조 용언 \'주다\', \'싶다\'가 사용되었다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 음운 규칙 오해"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q06', 'W1_LIT_P5', 'wittgenstein', '논리추론형', '(가)의 \'이것들\'과 (나)의 \'그 무엇\'에 대한 설명으로 가장 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"\'이것들\'과 \'그 무엇\'은 모두 인간의 힘으로 통제할 수 없는 초자연적 힘을 가리킨다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"과도한 일반화"},{"choice_id":"B","text":"\'이것들\'은 화자를 현혹시키는 대상을, \'그 무엇\'은 송화가 극복해야 할 장애물을 의미한다.","vector":{"문장 독해력":-4,"국어 관련 배경지식":-3},"error_path":"부정적 의미 부여 오류"},{"choice_id":"C","text":"\'이것들\'은 화자가 깨달은 사랑의 속성을, \'그 무엇\'은 유봉이 추구하는 소리의 본질(한)을 의미한다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"\'이것들\'은 변화무쌍한 세태를, \'그 무엇\'은 변하지 않는 진리를 상징한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"시어 의미 오해"},{"choice_id":"E","text":"\'이것들\'은 현실의 구속을, \'그 무엇\'은 예술적 자유를 의미한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"개념 대입 오류"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q07', 'W1_LIT_P5', 'wittgenstein', '논리추론형', '(나)에서 \'송화\'가 춘향가의 \'이별 대목\'을 부르는 행위에 담긴 의미로 가장 적절한 것은?', NULL, 'E', '[{"choice_id":"A","text":"떠나간 동호에 대한 그리움과 재회에 대한 희망을 노래한다.","vector":{"문장 독해력":-3,"국어 관련 배경지식":-2},"error_path":"상황 해석 오류"},{"choice_id":"B","text":"아버지 유봉에 대한 원망을 간접적으로 표출한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"심리 파악 오류"},{"choice_id":"C","text":"판소리 실력을 과시하여 동호의 마음을 돌리려 한다.","vector":{"문장 독해력":-4,"논리 사고력":-3},"error_path":"행위 의도 왜곡"},{"choice_id":"D","text":"자신의 기구한 운명을 한탄하며 세상을 비관한다.","vector":{"문장 독해력":-3,"논리 사고력":-2},"error_path":"태도 파악 오류"},{"choice_id":"E","text":"동호와의 이별을 운명으로 받아들이고 한(恨)을 예술적으로 승화시킨다.","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q08', 'W1_LIT_P5', 'wittgenstein', '논리추론형', '(가)의 화자가 지향하는 삶의 태도를 한자 성어로 표현할 때 가장 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"맥수지탄(麥秀之嘆) - 나라가 망한 것을 한탄함.","vector":{"국어 관련 배경지식":-4,"어휘력":-3},"error_path":"상황 불일치 (1)"},{"choice_id":"B","text":"고진감래(苦盡甘來) - 고생 끝에 낙이 옴.","vector":{"국어 관련 배경지식":-3,"어휘력":-2},"error_path":"인과 관계 불일치"},{"choice_id":"C","text":"일편단심(一片丹心) - 한 조각의 붉은 마음, 변치 않는 참된 마음.","vector":{"국어 관련 배경지식":10,"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"무아지경(無我之境) - 정신이 한곳에 쏠려 자신을 잊어버리는 경지.","vector":{"국어 관련 배경지식":-3,"어휘력":-2},"error_path":"한자성어 적용 제한"},{"choice_id":"E","text":"안빈낙도(安貧樂道) - 가난하면서도 편안한 마음으로 도를 즐김.","vector":{"국어 관련 배경지식":-3,"어휘력":-2},"error_path":"상황 불일치"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q09', 'W1_LIT_P5', 'wittgenstein', '서술형', '(가)에서 \'환장할 일\'이라고 표현한 이유를 화자의 심리 상태와 관련지어 서술하시오. (40자 내외)', NULL, NULL, '[]', '그리움이 너무나 간절하고 깊어 영원히 멈출 수 없다는 것을 깨달았을 때의 벅찬 감정 때문이다.', '[{"criteria_id":1,"condition":"\'간절함\', \'벅참\', \'절실함\' 등의 심리 표현 포함","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"\'영원히 멈출 수 없음\' 혹은 \'지속성\'에 대한 인식 포함","score":5,"vector":{"국어 관련 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_LIT_P5_Q10', 'W1_LIT_P5', 'wittgenstein', '서술형', '(나)에서 유봉이 송화의 눈을 멀게 한 \'예술적 이유\'를 찾아 서술하시오. (30자 내외)', NULL, NULL, '[]', '송화의 마음에 맺힌 한(恨)을 심어 주어 소리를 완성시키기 위해서였다.', '[{"criteria_id":1,"condition":"\'한(恨)\'을 심어 준다는 내용 포함","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"\'소리의 완성\' 또는 \'예술적 성취\' 언급","score":5,"vector":{"국어 관련 배경지식":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q01', 'W1_NON_P3', 'wittgenstein', '지문근거형', '윗글의 내용과 일치하는 것은?', NULL, 'B', '[{"choice_id":"A","text":"프레게는 \'샛별\'과 \'개밥바라기\'가 뜻은 같지만 지시체가 다르다고 보았다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"개념 혼동"},{"choice_id":"B","text":"프레게는 빈 지시어가 포함된 문장은 참도 거짓도 아닌 진리치 공백 상태라고 보았다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"프레게와 러셀은 모두 빈 지시어 문제를 해결하기 위해 \'뜻\'의 개념을 도입했다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"공통점/차이점 혼동"},{"choice_id":"D","text":"러셀은 한정 기술구를 고유명사와 동일한 기능을 하는 지시어로 간주했다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"이론 차이 혼동"},{"choice_id":"E","text":"러셀은 언어의 표면적 문법 구조와 논리적 구조가 일치한다고 주장했다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"내용 왜곡"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q02', 'W1_NON_P3', 'wittgenstein', '논리추론형', '러셀의 관점에서 \'현재 한국의 왕은 미혼이다\'라는 문장을 분석할 때 적절한 판단은?', NULL, 'D', '[{"choice_id":"A","text":"지시하는 대상이 없으므로 무의미하다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"러셀 이론 오해"},{"choice_id":"B","text":"\'한국의 왕\'이라는 개념은 존재하므로 문장의 진리치는 상황에 따라 달라진다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"개념/대상 혼동"},{"choice_id":"C","text":"문법적으로 완벽한 문장이므로 무조건 참이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"형식 논리 오해"},{"choice_id":"D","text":"\'한국의 왕이 존재한다\'는 명제가 거짓이므로 전체 문장은 거짓이다.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"E","text":"뜻은 있지만 지시체가 없으므로 참도 거짓도 아니다.","vector":{"논리 사고력":-4,"비문학 배경지식":-3},"error_path":"프레게 이론과 혼동"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q03', 'W1_NON_P3', 'wittgenstein', '어휘단독형', '다음 <보기>의 단어 뜻풀이가 적절하지 않은 것은?', '<보기>\n① 해명(解明): 까닭이나 내용을 풀어서 밝힘.\n② 결여(缺如): 마땅히 있어야 할 것이 빠져서 없거나 모자람.\n③ 환원(還元): 본디의 상태나 형상으로 다시 돌아가게 함.\n④ 야기(惹起): 일이나 사건 따위를 끌어 일으킴.\n⑤ 해소(解消): 어떤 일의 결과를 미리 짐작하여 앎.', 'E', '[{"choice_id":"A","text":"④ 야기","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 의미 혼동"},{"choice_id":"B","text":"① 해명","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 문맥 부적합"},{"choice_id":"C","text":"③ 환원","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 유의어 오해"},{"choice_id":"D","text":"② 결여","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 범주 혼동"},{"choice_id":"E","text":"⑤ 해소","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q04', 'W1_NON_P3', 'wittgenstein', '어휘단독형', '다음 <보기>의 단어들의 표준 발음으로 적절하지 않은 것은?', '<보기>\n① 맑다\n② 흙 위\n③ 넓다\n④ 밟다\n⑤ 핥다', 'E', '[{"choice_id":"A","text":"③ [널따]","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 문법 규칙 오해"},{"choice_id":"B","text":"⑤ [할따]","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 형태소 분석 오류"},{"choice_id":"C","text":"② [흘귀]","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 품사 판별 오류"},{"choice_id":"D","text":"① [막따]","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항 오독: 음운 규칙 오해"},{"choice_id":"E","text":"④ [발따]","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q05', 'W1_NON_P3', 'wittgenstein', '어휘단독형', '다음 <보기>의 문장 구조에 대한 설명으로 옳은 것은?', '<보기>\nㄱ. 우리는 그가 범인임을 깨달았다.\nㄴ. 비가 소리도 없이 내린다.', 'C', '[{"choice_id":"A","text":"ㄱ과 ㄴ 모두 주어와 서술어의 관계가 한 번만 나타나는 홑문장이다.","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"홑문장/겹문장 구분 오류"},{"choice_id":"B","text":"ㄱ과 ㄴ 모두 이어진 문장 중 종속적으로 이어진 문장에 해당한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"이어진 문장/안은 문장 구분 오류"},{"choice_id":"C","text":"ㄱ은 명사절을 안은 문장이고, ㄴ은 부사절을 안은 문장이다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"D","text":"ㄱ은 인용절을 안은 문장이고, ㄴ은 명사절을 안은 문장이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"안은문장 종류 혼동 (1)"},{"choice_id":"E","text":"ㄱ은 서술절을 안은 문장이고, ㄴ은 관형절을 안은 문장이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"안은문장 종류 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q06', 'W1_NON_P3', 'wittgenstein', '논리추론형', '프레게의 입장에서 \'개밥바라기\'와 \'샛별\'의 관계를 설명한 것으로 가장 적절한 것은?', NULL, 'E', '[{"choice_id":"A","text":"두 표현은 서로 아무런 관계가 없다.","vector":{"논리 사고력":-2,"비문학 배경지식":-2},"error_path":"상식 오류"},{"choice_id":"B","text":"뜻과 지시체가 모두 동일하다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"프레게 이론 오해"},{"choice_id":"C","text":"뜻과 지시체가 모두 다르다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"프레게 이론 오해 (2)"},{"choice_id":"D","text":"뜻은 같지만 지시체가 다르다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"프레게 이론 오해 (1)"},{"choice_id":"E","text":"뜻은 다르지만 지시체는 동일하다.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q07', 'W1_NON_P3', 'wittgenstein', '지문근거형', '러셀이 \'기술 이론\'을 통해 해결하고자 했던 주된 철학적 문제는 무엇인가?', NULL, 'A', '[{"choice_id":"A","text":"존재하지 않는 대상을 지시하는 문장의 의미와 진리치 문제","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"도덕적 판단의 객관적 기준을 세우는 문제","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"주제 이탈 (1)"},{"choice_id":"C","text":"국가 간의 언어 번역 가능성을 탐구하는 문제","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"주제 이탈 (3)"},{"choice_id":"D","text":"인간의 언어 습득 능력이 선천적인지 후천적인지 밝히는 문제","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"주제 이탈 (2)"},{"choice_id":"E","text":"과학적 지식의 확실성을 입증하는 문제","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"주제 이탈"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q08', 'W1_NON_P3', 'wittgenstein', '논리추론형', '윗글을 바탕으로 <보기>의 주장에 대해 비판할 내용으로 가장 적절한 것은?', '<보기>\n**철수**: "\'황금산은 높다\'라는 문장을 봐. 실제로 황금산은 없지만, 우리는 이 문장의 의미를 이해할 수 있어. 그렇다면 \'황금산\'이라는 단어는 어딘가에 존재하는 대상을 가리키고 있는 것이 분명해. 현실 세계가 아니라면, 일종의 관념 세계에라도 그 대상이 존재해야만 해."', 'B', '[{"choice_id":"A","text":"관념 세계에 존재한다는 설명은 과학적으로 증명되었으므로 타당한 주장이야.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"사실 판단 오류"},{"choice_id":"B","text":"프레게라면 \'황금산\'의 뜻은 있지만 지시체는 없다고 말할 거야. 의미를 이해한다고 해서 반드시 대상이 존재해야 하는 건 아니야.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"러셀의 입장에서 보면 \'황금산\'은 고유명사이므로 반드시 지시체가 있어야 해.","vector":{"논리 사고력":-4,"비문학 배경지식":-3},"error_path":"러셀 이론 오해"},{"choice_id":"D","text":"맞아. 우리가 상상할 수 있는 모든 것은 현실에 존재한다고 봐야 해.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"비판적 사고 부재"},{"choice_id":"E","text":"\'황금산\'은 동음이의어일 가능성이 높으니 문맥을 더 살펴봐야 해.","vector":{"논리 사고력":-2,"비문학 배경지식":-2},"error_path":"논점 일탈"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q09', 'W1_NON_P3', 'wittgenstein', '서술형', '프레게가 \'뜻\'과 \'지시체\'를 구분하게 된 계기가 된 언어 현상은 무엇인지 서술하시오. (30자 내외)', NULL, NULL, '[]', '동일성 진술(a=b)이 정보적 가치를 지니는 현상을 설명하기 위해서.', '[{"criteria_id":1,"condition":"\'동일성 진술\' 또는 \'a=b\' 언급","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"\'정보적 가치\' 또는 \'인식적 가치\' 언급","score":5,"vector":{"비문학 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P3_Q10', 'W1_NON_P3', 'wittgenstein', '서술형', '러셀이 \'빈 지시어\'가 포함된 문장의 진리치 문제를 해결한 방법을 서술하시오. (50자 내외)', NULL, NULL, '[]', '문장을 논리적 구조로 분석하여 존재 연언이 거짓이면 전체 문장이 \'거짓\'이 되도록 하여 해결했다.', '[{"criteria_id":1,"condition":"\'논리적 구조 분석\' 또는 \'한정 기술구 분석\' 언급","score":5,"vector":{"비문학 배경지식":10}},{"criteria_id":2,"condition":"진리치를 \'거짓\'으로 판단함 언급","score":5,"vector":{"논리 사고력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q01', 'W1_NON_P5', 'wittgenstein', '지문근거형', '윗글의 내용과 일치하지 않는 것은?', NULL, 'A', '[{"choice_id":"A","text":"방관자 킬러 T세포는 T세포 수용체를 통해 특정 항원을 인식한 후 활성화된다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"자가면역 질환의 치료를 위해 방관자 T세포의 제어 기술이 연구되고 있다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"C","text":"방관자 킬러 T세포의 과도한 활성화는 정상 조직에 손상을 줄 수 있다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"D","text":"방관자 킬러 T세포는 초기 감염 시 빠른 방어 작용을 수행할 수 있다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"E","text":"염증성 사이토카인은 방관자 킬러 T세포를 활성화시키는 신호 역할을 한다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"부정형 문항 오독: 과도한 일반화"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q02', 'W1_NON_P5', 'wittgenstein', '논리추론형', '윗글을 바탕으로 추론한 내용으로 가장 적절한 것은?', NULL, 'D', '[{"choice_id":"A","text":"방관자 킬러 T세포는 항원 인식 과정이 없으므로 사이토카인에도 반응하지 않을 것이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"전제 부정 오류"},{"choice_id":"B","text":"항원 회피 능력을 가진 암세포는 방관자 킬러 T세포의 공격을 완벽하게 피할 수 있다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"추론 오류 (본문 내용 반대)"},{"choice_id":"C","text":"특정 항원 특이 T세포가 없는 환자는 방관자 킬러 T세포만으로 모든 질병을 완치할 수 있다.","vector":{"논리 사고력":-4,"비문학 배경지식":-3},"error_path":"과도한 일반화"},{"choice_id":"D","text":"NKG2D 등의 수용체를 억제하면 자가면역 질환의 증상을 완화할 수 있는 가능성이 있다.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"E","text":"면역 반응의 효율성만을 고려한다면 방관자 킬러 T세포를 모두 제거하는 것이 유리하다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"가치 판단 오류"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q03', 'W1_NON_P5', 'wittgenstein', '어휘단독형', '다음 <보기>의 설명을 참고하여 ㉠~㉤의 단어 뜻풀이가 적절하지 않은 것은?', '<보기>\n㉠ 인지(認知): 어떤 사실을 인정하여 앎.\n㉡ 무관(無關): 관계가 없음.\n㉢ 증식(增殖): 늘어서 불어남.\n㉣ 관여(關與): 어떤 일에 관계하여 참여함.\n㉤ 정밀(精密): 아주 정교하고 치밀함.', 'C', '[{"choice_id":"A","text":"㉡ : 무관","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 의미 혼동"},{"choice_id":"B","text":"㉣ : 관여","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 문맥 부적합"},{"choice_id":"C","text":"해당 단어들은 모두 문맥에 맞게 적절하게 사용되었다.","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"D","text":"㉢ : 증식","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 유의어 오해"},{"choice_id":"E","text":"㉠ : 인지","vector":{"어휘력":-3,"문장 독해력":-2},"error_path":"부정형 문항 오독: 어휘 범주 혼동"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q04', 'W1_NON_P5', 'wittgenstein', '어휘단독형', '다음 <보기>는 윗글의 문장 성분을 분석한 것이다. 적절하지 않은 것은?', '<보기>\n① 면역 체계에서 킬러 T세포는 바이러스를 제거한다.\n② 최근 연구들은 방관자 킬러 T세포의 역할을 주목하고 있다.\n③ 이 세포들은 독성 물질을 분비하거나 인터페론 감마를 방출한다.', 'A', '[{"choice_id":"A","text":"②에서 주어는 \'역할\'이고, \'최근 연구들은\'은 부사어이다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"①에서 \'면역 체계에서\'는 장소를 나타내는 부사어이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항에서 올바른 성분 분석을 선택"},{"choice_id":"C","text":"①에서 \'제거한다\'는 목적어 \'바이러스를\'을 필요로 하는 타동사이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항에서 올바른 동사 성격을 선택"},{"choice_id":"D","text":"②에서 \'주목하고 있다\'는 본용언과 보조 용언이 결합하여 서술어 역할을 한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항에서 올바른 서술어 구성을 선택"},{"choice_id":"E","text":"③은 \'이 세포들은 독성 물질을 분비한다\'와 \'(이 세포들은) 인터페론 감마를 방출한다\'가 대등하게 이어진 문장이다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"부정형 문항에서 올바른 문장 구조를 선택"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q05', 'W1_NON_P5', 'wittgenstein', '어휘단독형', '윗글의 단어들에 적용된 음운 변동에 대한 설명으로 옳은 것은?', '<보기>\nㄱ. **생략**[생냑]\nㄴ. **협력**[혐녁]\nㄷ. **항원**[항원]\nㄹ. **독립**[동닙]', 'E', '[{"choice_id":"A","text":"ㄷ: 두음 법칙이 적용되어 [양원]으로 발음해야 한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"두음 법칙 오해"},{"choice_id":"B","text":"ㄹ: 자음군 단순화가 적용되어 [도립]으로 발음해야 한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"자음군 단순화 오해"},{"choice_id":"C","text":"ㄱ, ㄴ, ㄷ, ㄹ 모두 거센소리되기가 일어난다.","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-3},"error_path":"음운 변동 식별 오류"},{"choice_id":"D","text":"ㄴ: 유음화가 일어나 [혈력]으로 발음해야 한다.","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-2},"error_path":"음운 변동 적용 오해"},{"choice_id":"E","text":"ㄱ: \'ㄴ\' 첨가 후 비음화가 일어난다.","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10},"error_path":"정답"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q06', 'W1_NON_P5', 'wittgenstein', '지문근거형', '윗글의 \'방관자 킬러 T세포\' 활성화 원리로 적절한 것은?', NULL, 'B', '[{"choice_id":"A","text":"체온 상승과 같은 물리적 자극에 의해서만 활성화된다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"내용 불일치"},{"choice_id":"B","text":"주변 환경의 염증성 사이토카인 신호를 받아 활성화된다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"T세포 수용체가 특정 항원과 결합하여 활성화된다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"기존 T세포와 혼동"},{"choice_id":"D","text":"바이러스의 DNA를 직접 복제하여 활성화된다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"과학적 원리 오해"},{"choice_id":"E","text":"암세포가 분비하는 항체와 반응하여 활성화된다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"항체/항원 오해"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q07', 'W1_NON_P5', 'wittgenstein', '논리추론형', '윗글을 바탕으로 [A형 간염 환자]의 간 손상 원인을 추론한 내용으로 가장 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"간세포가 사이토카인을 과다 분비하여 스스로 사멸했기 때문이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"기제 오해"},{"choice_id":"B","text":"바이러스가 간세포 내에서 증식하여 세포를 직접 터뜨렸기 때문이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"인과 관계 단순화"},{"choice_id":"C","text":"활성화된 방관자 킬러 T세포가 감염되지 않은 정상 간세포까지 공격했기 때문이다.","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"항원 특이 T세포가 바이러스에 감염된 간세포만을 선택적으로 제거했기 때문이다.","vector":{"논리 사고력":-3,"비문학 배경지식":-2},"error_path":"정상 면역 반응 설명"},{"choice_id":"E","text":"면역 체계가 작동을 멈추어 바이러스 방어에 실패했기 때문이다.","vector":{"논리 사고력":-2,"비문학 배경지식":-2},"error_path":"상황 오해"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q08', 'W1_NON_P5', 'wittgenstein', '지문근거형', '방관자 킬러 T세포의 \'두 얼굴(이중성)\'을 가장 잘 요약한 것은?', NULL, 'C', '[{"choice_id":"A","text":"암세포는 잘 죽이지만 바이러스는 죽이지 못한다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"능력 제한 오해"},{"choice_id":"B","text":"사이토카인에는 반응하지만 케모카인에는 반응하지 않는다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"특성 오해"},{"choice_id":"C","text":"초기 바이러스 방어에는 유리하지만, 과도하면 정상 조직 손상을 유발할 수 있다.","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"선천 면역에는 기여하지만 적응 면역에는 방해가 된다.","vector":{"문장 독해력":-3,"비문학 배경지식":-2},"error_path":"개념 혼동"},{"choice_id":"E","text":"낮에는 활성화되고 밤에는 비활성화된다.","vector":{"문장 독해력":-2,"비문학 배경지식":-2},"error_path":"사실 무근"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q09', 'W1_NON_P5', 'wittgenstein', '서술형', '방관자 킬러 T세포가 활성화되는 구체적인 조건을 본문에서 찾아 서술하시오. (30자 내외)', NULL, NULL, '[]', '감염 부위 주변에서 분비되는 염증성 사이토카인의 신호를 받을 때 활성화된다.', '[{"criteria_id":1,"condition":"\'염증성 사이토카인\' 언급","score":5,"vector":{"비문학 배경지식":10}},{"criteria_id":2,"condition":"\'신호\' 또는 \'자극\' 언급","score":5,"vector":{"문장 독해력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('W1_NON_P5_Q10', 'W1_NON_P5', 'wittgenstein', '서술형', '윗글을 바탕으로 방관자 킬러 T세포와 관련된 질환의 발병 원인을 서술하시오. (40자 내외)', NULL, NULL, '[]', '항원 인식 과정 없이 정상 조직을 무차별적으로 공격하여 염증과 조직 손상을 일으키기 때문이다.', '[{"criteria_id":1,"condition":"\'항원 인식 과정 생략\' 또는 \'무차별적 공격\' 언급","score":5,"vector":{"논리 사고력":10}},{"criteria_id":2,"condition":"\'정상 조직 손상\' 또는 \'염증 유발\' 언급","score":5,"vector":{"비문학 배경지식":10}}]', NULL, 10);
